/* ================================================================
 * XP Messenger —— 酒馆变成一台 Windows XP：桌面、任务栏、开始菜单，聊天就是 Windows Messenger 的对话窗口
 *
 * 作者：mangosagocreamwithpomelo（Discord）
 * 设计与实现：Claude Opus 5.5（Anthropic）
 * 窗口、按钮、滚动条、表单控件参考 XP.css（MIT，Adam Hammad, Jordan Scales）；
 * 桌面图标、壁纸是照着 XP 的样子重新画的，不含微软的原图。
 *
 * 怎么找到酒馆的各个面板：
 *   开始 = 角色（开始菜单里的程序就是你的角色卡）
 *   桌面：我的电脑 = 用户设置　我的文档 = 世界书　网上邻居 = API 连接　控制面板 = 扩展
 *   对话窗口右边「我想…」：编辑我的个人资料 = 人设　更改对话背景 = 背景　调整回复方式 = 预设　设置消息格式 = 高级格式
 *   打开的窗口右上角红色 × 就是关闭
 * ================================================================ */

/* ================================================================
 * 可改区：想调整的都在这里，改完点空白处即可生效。改坏了重新导入主题就能恢复。
 * ================================================================ */
html:root {
    /* —— 对话 —— */
    --xp-chat-font: SimSun, '宋体', 'Songti SC', 'Noto Serif SC', serif;   /* 消息的字体（Messenger 中文版默认宋体） */
    --xp-chat-size: 14px;            /* 消息字号 */
    --xp-chat-line: 1.6;             /* 消息行距 */
    --xp-says: ' 说：';              /* 名字后面那句 */
    --xp-title-suffix: ' - 对话';    /* 窗口标题：「星野澪 - 对话」 */
    --xp-to: '收件人：';             /* 对话顶上那一条 */
    --xp-user: 'Administrator';      /* 开始菜单顶上的用户名 */
    --xp-status: '切勿在即时消息对话中透露您的密码或信用卡号。';   /* 电脑：窗口最底下状态栏的字 */
    --xp-typing: '对方正在输入消息...';                          /* 电脑：生成回复时状态栏的字 */

    /* —— 窗口 —— */
    --xp-win-max: 1120px;            /* 电脑：对话窗口最宽多少 */
    --xp-win-side: 104px;            /* 电脑：窗口两边至少露出多少桌面（左边要放桌面图标） */
    --xp-win-gap: 16px;              /* 电脑：窗口上下露出多少桌面 */
    --xp-side-w: 178px;              /* 电脑：右边「我想…」那一栏的宽 */
    --xp-m-pad: 10px;                /* 手机：消息到窗口左右两边的距离 */

    /* —— 颜色、字体（配色方案在主题设置里选；不装主题伴侣的话导入「XP Messenger · 橄榄绿」等） —— */
    --xp-desktop: #3A6EA5;           /* 桌面底色（壁纸没加载出来时） */
    --xp-ui-font: SimSun, '宋体', Tahoma, 'PingFang SC', 'Noto Sans SC', sans-serif;   /* 菜单、按钮、图标名（中文 XP 连英文都是宋体） */
    --xp-title-font: 'Trebuchet MS', SimSun, '宋体', 'PingFang SC', sans-serif;       /* 标题栏 */
}
/* ======================== 可改区结束 ======================== */

