/* ==== themes/xp/schemes/blue.css ==== */
/* 配色：Luna 蓝（XP 默认）
 * 橄榄绿、银色是另外两份（olive.css / silver.css），变量一一对应；主题设置里切换就是整份换掉 */
:root {
    --xp-face: #ECE9D8;              /* 窗口、对话框的米色 */

    /* 标题栏、窗口边 */
    --xp-title-grad: linear-gradient(180deg, #0997FF 0%, #0053EE 8%, #0050EE 40%, #0066FF 88%, #0066FF 93%, #005BFF 95%, #003DD7 96%, #003DD7 100%);
    --xp-title-grad-off: linear-gradient(180deg, #7996DE 0%, #7B9AE3 8%, #7C9DE6 40%, #8BAAED 88%, #8BAAED 93%, #8AA6EB 95%, #7792E2 96%, #7792E2 100%);
    --xp-title-ink: #FFFFFF;
    --xp-title-shadow: #0F1089;
    --xp-title-edge: inset 1px 1px #0831D9, inset -1px 0 #001EA0, inset 2px 2px #166AEE, inset -2px 0 #003BDA;
    --xp-frame-shadow: inset -1px -1px #00138C, inset 1px 1px #0831D9, inset -2px -2px #001EA0, inset 2px 2px #166AEE, inset -3px -3px #003BDA, inset 3px 3px #0855DD;

    /* Messenger 窗口里面 */
    --xp-body-blue: #0148B2;         /* 窗口里面的深蓝（收件人那一条、白框之间的缝） */
    --xp-to-ink: #BBCEEB;            /* 「收件人：星野澪」的字 */
    --xp-box-edge: #7DA2D9;          /* 白框的边 */
    --xp-strip: #D6DFF7;             /* 工具条（动作、表情符号那一行） */
    --xp-side-bg: linear-gradient(180deg, #7BA2E7, #6375D6);   /* 右边任务窗格 */
    --xp-side-head: linear-gradient(90deg, #FFFFFF, #C6D3F7);   /* 窗格里小标题 */
    --xp-side-box: #D6DFF7;
    --xp-side-edge: #C6D3F7;
    --xp-link: #215DC6;
    --xp-link-hover: #428EFF;
    --xp-group-ink: #0046D5;         /* 设置里分组小标题 */

    /* 控件 */
    --xp-input-edge: #7F9DB9;
    --xp-btn-edge: #003C74;
    --xp-sel: #316AC5;               /* 选中、鼠标移上去 */
    --xp-sel-ink: #FFFFFF;
    --xp-thumb: #C8D6FB;             /* 滚动条滑块 */
    --xp-thumb-shadow: inset -3px 0 #BAD1FC, inset 1px 1px #B7CAF5;

    /* 任务栏 */
    --xp-tb-grad: linear-gradient(180deg, #1F2F86 0, #3165C4 3%, #3682E5 6%, #4490E6 10%, #3883E5 12%, #2B71E0 15%, #2663DA 18%, #235BD6 20%, #2258D5 23%, #2157D6 38%, #245DDB 54%, #2562DF 86%, #245FDC 89%, #2158D4 92%, #1D4EC0 95%, #1941A5 98%);
    --xp-tray-grad: linear-gradient(180deg, #0C59B9 1%, #139EE9 6%, #18B5F2 10%, #139BEB 14%, #1290E8 19%, #0D8DEA 63%, #0D9FF1 81%, #0F9EED 88%, #119BE9 91%, #1392E2 94%, #137ED7 97%, #095BC9 100%);
    --xp-tray-edge: #1042AF;
    --xp-tray-ink: #FFFFFF;
    --xp-task-btn: #1E52B7;          /* 任务栏上按下去的窗口按钮 */
    --xp-task-ink: #FFFFFF;

    /* 开始菜单 */
    --xp-sm-head-grad: linear-gradient(180deg, #1868CE 0%, #0E60CB 12%, #0E60CB 20%, #1164CF 32%, #1667CF 33%, #1B6CD3 47%, #1E70D9 54%, #2476DC 60%, #297AE0 65%, #3482E3 77%, #3786E5 79%, #428EE9 90%, #4791EB 100%);
    --xp-sm-head-edge: #3C8EF3;
    --xp-sm-head-ink: #FFFFFF;
    --xp-sm-head-shadow: #0A3D8A;
    --xp-sm-foot-grad: linear-gradient(180deg, #4282D6 0%, #3B7CD4 10%, #2E6DCB 50%, #1E5EC4 90%, #1A55B8 100%);
    --xp-sm-foot-edge: #6FA0E6;
    --xp-sm-frame: #0831D9;
    --xp-sm-col: #D3E5FA;            /* 右栏 */
    --xp-sm-col-edge: #95BDEE;
    --xp-sm-ink: #00136B;            /* 右栏的字 */
}
/* ==== end themes/xp/schemes/blue.css ==== */
/* ==== themes/xp/schemes/blue-art.css ==== */
/* Luna 蓝的按钮、滚动条图就是 art.css 里那一套，这里空着；橄榄绿、银色换成 olive-art.css / silver-art.css（tools/xp/art.mjs 生成） */
/* ==== end themes/xp/schemes/blue-art.css ==== */
/* ==== shared/light-mode.css ==== */
/* 浅色主题专用：酒馆有不少写死的「白色半透明」文字/边框（--white30a 等）和深灰底（--grey30），
 * 在浅色背景上会看不清。这里把它们重映射为「正文色半透明」，语义上仍是「前景色的淡化版」。 */
:root {
    --white20a: color-mix(in srgb, var(--SmartThemeBodyColor) 20%, transparent);
    --white30a: color-mix(in srgb, var(--SmartThemeBodyColor) 40%, transparent);
    --white50a: color-mix(in srgb, var(--SmartThemeBodyColor) 70%, transparent);
    --white60a: color-mix(in srgb, var(--SmartThemeBodyColor) 75%, transparent);
    --white70a: color-mix(in srgb, var(--SmartThemeBodyColor) 80%, transparent);
    /* 黑色半透明多用作输入框、面板底色，在浅色纸面上会发脏，改为极淡的正文色 */
    --black30a: color-mix(in srgb, var(--SmartThemeBodyColor) 6%, transparent);
    --black50a: color-mix(in srgb, var(--SmartThemeBodyColor) 10%, transparent);
    --black60a: color-mix(in srgb, var(--SmartThemeBodyColor) 12%, transparent);
    --black70a: color-mix(in srgb, var(--SmartThemeBodyColor) 14%, transparent);
    --grey30a: color-mix(in srgb, var(--SmartThemeBodyColor) 8%, transparent);
    --interactable-outline-color: var(--SmartThemeBodyColor);
    --interactable-outline-color-faint: color-mix(in srgb, var(--SmartThemeBodyColor) 20%, transparent);
}

/* 思维链折叠条：默认深灰底 */
.mes_reasoning_header {
    background-color: color-mix(in srgb, var(--SmartThemeBodyColor) 8%, transparent);
}

/* 楼层号等默认 opacity:.7，浅底上对比不足 */
.mes .mesIDDisplay,
.mes .tokenCounterDisplay,
.mes .mes_timer {
    opacity: 0.9;
}

/* 设置区块标题：默认是深色渐变，改为淡色块 + 主题色左边 */
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    background-image: linear-gradient(90deg, color-mix(in srgb, var(--SmartThemeQuoteColor) 14%, transparent), transparent);
    border-left: 3px solid var(--SmartThemeQuoteColor);
}
/* ==== end shared/light-mode.css ==== */
/* ==== shared/entry-states.css ==== */
/* 世界书 / 预设条目的开关态（碎碎念第 1 条）
 * 酒馆默认：禁用世界书条目 opacity:.4 + 灰度；禁用预设名称写死 white30a，都会让标题看不清。
 * 这里改成：标题始终保持可读，用「左侧线条（颜色 + 线型）+ 背景 + 开关图标」多重信号区分开/关。
 * 主题可覆盖下列变量调整外观（颜色默认从 SmartTheme 变量派生，不写死）。
 * 默认外观 = 「斜纹底 + 斜体标题」（用户认可的设计，存档供以后的主题使用）。 */
:root {
    --st-entry-on: var(--SmartThemeQuoteColor);            /* 启用 */
    --st-entry-constant: var(--SmartThemeUnderlineColor);  /* 常驻（蓝灯） */
    --st-entry-off: color-mix(in srgb, var(--SmartThemeBodyColor) 35%, transparent); /* 禁用线条 */
    --st-entry-off-bg: repeating-linear-gradient(-45deg,
        color-mix(in srgb, var(--SmartThemeBodyColor) 5%, transparent) 0 6px,
        transparent 6px 12px);
    --st-entry-bar: 4px;
    /* 线型：图例式区分（double 需要 bar ≥ 3px 才看得出） */
    --st-entry-on-style: solid;
    --st-entry-constant-style: solid;
    --st-entry-off-style: dashed;
    /* 禁用条目标题 */
    --st-entry-off-title-color: var(--SmartThemeBodyColor);
    --st-entry-off-title-style: italic;
    --st-entry-radius: 6px;
}

/* ---------- 世界书 ---------- */
#world_popup_entries_list .world_entry {
    border-left: var(--st-entry-bar) var(--st-entry-on-style) var(--st-entry-on);
    border-radius: var(--st-entry-radius);
}

/* 常驻但已关闭的条目按「关闭」显示 */
#world_popup_entries_list .world_entry:not(.disabledWIEntry):has(select[name="entryStateSelector"] option[value="constant"]:checked) {
    border-left-width: var(--st-entry-constant-bar, var(--st-entry-bar));
    border-left-style: var(--st-entry-constant-style);
    border-left-color: var(--st-entry-constant);
}

#world_popup_entries_list .world_entry.disabledWIEntry,
#world_popup_entries_list .world_entry.disabledWIEntry:hover {
    opacity: 1;
    filter: none;
    border-left-style: var(--st-entry-off-style);
    border-left-color: var(--st-entry-off);
    background-image: var(--st-entry-off-bg);
}

#world_popup_entries_list .world_entry.disabledWIEntry textarea[name="comment"] {
    color: var(--st-entry-off-title-color);
    font-style: var(--st-entry-off-title-style);
}

/* 开关图标：开 = 实心主题色、不透明；关 = 正文色淡化。酒馆默认给图标 opacity .4，会让「开」反而比「关」暗 */
#world_popup_entries_list .world_entry .killSwitch.fa-toggle-on {
    color: var(--st-entry-on);
    opacity: 1;
}

#world_popup_entries_list .world_entry .killSwitch.fa-toggle-off {
    color: var(--SmartThemeBodyColor);
    opacity: 0.55;
}

/* ---------- 预设（Prompt Manager） ---------- */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    border-radius: var(--st-entry-radius);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) {
    border-left: var(--st-entry-bar) var(--st-entry-on-style) var(--st-entry-on);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
    border: 1px var(--st-entry-off-style) var(--st-entry-off);
    border-left-width: var(--st-entry-bar);
    background-image: var(--st-entry-off-bg);
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: var(--st-entry-off-title-color);
    font-style: var(--st-entry-off-title-style);
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-toggle-action {
    color: var(--st-entry-on);
    opacity: 1;
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .prompt-manager-toggle-action {
    color: var(--SmartThemeBodyColor);
    opacity: 0.55;
}
/* ==== end shared/entry-states.css ==== */
/* ==== shared/st-fixes.css ==== */
/* 酒馆界面的通用修正（从「纸上访谈」沉淀出来，第二套主题「银盐」起使用）
 * 酒馆很多按钮、图标、菜单默认半透明、带黑色模糊投影或暗红/绿色底，换了主题配色也发灰发脏。
 * 这里统一成实色，颜色全部来自下面几个变量，主题在自己的 :root 里改它们即可：
 *   --fx-ink      正文色            --fx-meta     次要文字
 *   --fx-accent   强调色            --fx-on-accent 强调色实底上的字
 *   --fx-hairline 细线              --fx-surface  输入框等浅底
 *   --fx-radius   圆角 */
:root {
    --fx-ink: var(--SmartThemeBodyColor);
    --fx-meta: color-mix(in srgb, var(--SmartThemeBodyColor) 62%, transparent);
    --fx-accent: var(--SmartThemeUnderlineColor);
    --fx-on-accent: var(--SmartThemeChatTintColor);
    --fx-hairline: var(--SmartThemeBorderColor);
    --fx-surface: color-mix(in srgb, var(--SmartThemeBodyColor) 4%, transparent);
    --fx-radius: 0;
    --fx-mes-buttons-idle: 0;   /* 电脑上消息按钮：0 = 鼠标移上去才出现，1 = 一直显示 */
}

/* ---- 消息按钮：电脑上悬停才出现；本身改成实色小图标（默认 30% 透明 + 黑色模糊投影） ---- */
@media (hover: hover) {
    #chat .mes .mes_buttons {
        opacity: var(--fx-mes-buttons-idle);
        transition: opacity 0.2s;
    }

    #chat .mes:hover .mes_buttons,
    #chat .mes .mes_buttons:focus-within {
        opacity: 1;
    }
}

#chat .mes .mes_button,
#chat .mes .extraMesButtons > div {
    opacity: 1;
    filter: none;
    color: var(--fx-meta);
    transition: color 0.2s;
}

#chat .mes .mes_button:hover,
#chat .mes .extraMesButtons > div:hover {
    color: var(--fx-accent);
}

/* 编辑消息时的按钮：默认绿底、红底 → 细线框；「完成」用强调色实底 */
#chat .mes .mes_edit_buttons .menu_button,
#chat .mes .mes_reasoning_edit_cancel,
#chat .mes .mes_reasoning_edit_done {
    background-color: transparent;
    opacity: 1;
    filter: none;
    color: var(--fx-meta);
}

#chat .mes .mes_edit_buttons .mes_edit_done,
#chat .mes .mes_reasoning_edit_done {
    background-color: var(--fx-accent);
    border-color: var(--fx-accent);
    color: var(--fx-on-accent);
}

/* 其余写死的黑色模糊投影（编辑按钮、展开按钮、收藏星标、图片计数、关闭叉） */
.mes_edit_buttons,
.extraMesButtons > div,
.ch_fav_icon,
.mes_img_swipe_counter,
.dragClose {
    filter: none;
}

/* ---- 预设条目里的小图标：默认 40% 透明 + 投影 ---- */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span,
#completion_prompt_manager .completion_prompt_manager_header_advanced span {
    filter: none;
    opacity: 1;
    color: var(--fx-meta);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span:hover {
    color: var(--fx-accent);
}

#completion_prompt_manager #completion_prompt_manager_list .prompt-manager-toggle-action.fa-toggle-on {
    color: var(--fx-accent);
}

#completion_prompt_manager .caution {
    color: var(--fx-accent);
}

/* ---- 按钮 ---- */
.menu_button {
    background-color: transparent;
    border: 1px solid var(--fx-hairline);
    border-radius: var(--fx-radius);
    transition: border-color 0.2s, color 0.2s, background-color 0.2s;
}

.menu_button:hover {
    border-color: var(--fx-accent);
    color: var(--fx-accent);
}

.menu_button.menu_button_default {
    box-shadow: none;
}

/* 确认框的「确定」：默认暗红底 → 强调色实底 */
.menu_button.popup-button-ok,
#dialogue_popup_ok,
#dialogue_del_mes_ok,
#bulk_tag_popup_reset,
#bulk_tag_popup_remove_mutual {
    background-color: var(--fx-accent);
    border-color: var(--fx-accent);
    color: var(--fx-on-accent);
}

.menu_button.popup-button-ok:hover,
#dialogue_popup_ok:hover,
#dialogue_del_mes_ok:hover,
#bulk_tag_popup_reset:hover,
#bulk_tag_popup_remove_mutual:hover {
    background-color: color-mix(in srgb, var(--fx-accent) 82%, var(--fx-ink));
    color: var(--fx-on-accent);
}

/* 收藏、角色世界书、聊天世界书亮起时：强调色实底，一眼可见 */
.fav_on,
.world_set,
.toggleEnabled {
    color: var(--fx-accent) !important;
}

.menu_button.fav_on,
.menu_button.world_set {
    background-color: var(--fx-accent);
    border-color: var(--fx-accent);
    color: var(--fx-on-accent) !important;
}

.menu_button.fav_on:hover,
.menu_button.world_set:hover {
    background-color: color-mix(in srgb, var(--fx-accent) 82%, var(--fx-ink));
    color: var(--fx-on-accent) !important;
}

/* 删除按钮：平时只是灰图标，悬停才变实心警示 */
.menu_button.red_button,
.menu_button.redWarningBG {
    background-color: transparent !important;
    color: var(--fx-meta);
}

.menu_button.red_button:hover,
.menu_button.redWarningBG:hover {
    background-color: var(--fx-accent) !important;
    border-color: var(--fx-accent);
    color: var(--fx-on-accent);
}

/* ---- 左下「≡」菜单和魔杖菜单：默认半透明 ---- */
.options-content a,
.list-group-item {
    opacity: 1;
    color: var(--fx-meta);
    transition: color 0.2s;
}

.options-content a:hover,
.list-group-item:hover,
#extensionsMenu > div:hover,
#extensionsMenu > .extension_container > div:hover {
    color: var(--fx-ink);
}

/* ---- 两侧贴边的面板：默认高度是「屏幕 − 顶栏」，底部空出一条缝 ---- */
.fillLeft,
.fillRight {
    max-height: 100vh;
    max-height: 100dvh;
}

/* ---- 多选列表（手机端「已启用世界书」）：默认每个 option 都是黑块 ---- */
select[multiple] option:not(:checked) {
    background-color: transparent;
    color: var(--fx-ink);
}

select[multiple] option:checked,
select[multiple]:focus option:checked {
    background: linear-gradient(color-mix(in srgb, var(--fx-accent) 24%, transparent), color-mix(in srgb, var(--fx-accent) 24%, transparent));
    color: var(--fx-ink);
}

/* ---- 标签与筛选圆钮：行内色块 → 细线 ---- */
#rm_print_characters_block .tag,
.tags .tag {
    border-color: var(--fx-hairline) !important;
    background-color: transparent !important;
    color: var(--fx-meta) !important;
    opacity: 1;
}

.rm_tag_filter .tag.actionable {
    background-color: transparent !important;
    border: 1px solid var(--fx-hairline) !important;
    color: var(--fx-meta) !important;
    filter: none;
    opacity: 1;
}

.rm_tag_filter .tag.actionable.selected {
    border-color: var(--fx-accent) !important;
    color: var(--fx-accent) !important;
}

/* 当前聊天角色 / 默认人设：不用绿色、金色 */
.avatar.is_active,
.group_member.is_active {
    outline: 1px solid var(--fx-accent);
    outline-offset: 2px;
}

.avatar-container.default_persona .avatar {
    outline-color: var(--fx-accent);
}

.ch_fav_icon {
    color: var(--fx-accent);
}

/* ---- 表单 ---- */
.text_pole,
select,
.select2-container .select2-selection {
    background-color: var(--fx-surface);
    border: 1px solid var(--fx-hairline);
    border-radius: var(--fx-radius);
}

.text_pole:focus,
select:focus {
    border-color: color-mix(in srgb, var(--fx-accent) 70%, transparent);
    outline: none;
}

input[type='checkbox'] {
    border-radius: var(--fx-radius);
    border: 1px solid var(--fx-meta);
    outline: 0;
    background-color: transparent;
    box-shadow: none;
    filter: none;
}

input[type='checkbox']:checked {
    border-color: var(--fx-accent);
    background-color: var(--fx-accent);
}

input[type='checkbox']::before {
    box-shadow: inset 1em 1em var(--fx-on-accent);
}

.neo-range-slider {
    height: 2px !important;
    margin-top: 10px !important;
    border-radius: 0 !important;
    background: color-mix(in srgb, var(--fx-ink) 30%, transparent) !important;
    box-shadow: none !important;
}

/* 展开图标：实心圆圈太重，换成细箭头 */
.inline-drawer-icon {
    font-size: var(--mainFontSize);
    color: var(--fx-meta);
    filter: none;
}

.inline-drawer-icon.fa-circle-chevron-down::before {
    content: '\f078';
}

.inline-drawer-icon.fa-circle-chevron-up::before {
    content: '\f077';
}

/* 多选删除消息时的选中底色：默认暗红 */
#chat .mes.selected {
    background-color: color-mix(in srgb, var(--fx-accent) 12%, transparent);
}

/* 系统通知 */
#toast-container > .toast {
    background-color: var(--SmartThemeBlurTintColor) !important;
    background-image: none;
    border: 1px solid var(--fx-hairline);
    border-left: 3px solid var(--fx-meta);
    border-radius: var(--fx-radius);
    box-shadow: 0 12px 32px var(--SmartThemeShadowColor);
    color: var(--fx-ink);
    opacity: 1;
}

#toast-container > .toast-warning,
#toast-container > .toast-error {
    border-left-color: var(--fx-accent);
}

::selection {
    background-color: color-mix(in srgb, var(--fx-accent) 26%, transparent);
}
/* ==== end shared/st-fixes.css ==== */
/* ==== themes/xp/base.css ==== */
/* Luna · 母版
 * 尺寸照 XP 默认（Luna 蓝、96 DPI）：标题栏 30、菜单栏 20、任务栏 30、滚动条 17，字是 Tahoma 8pt + 宋体 9pt。 */

:root {
    --xp-tb-h: 30px;                 /* 任务栏 */
    --xp-title-h: 30px;              /* 标题栏（含上边框） */
    --xp-menu-h: 21px;               /* 菜单栏 */
    --xp-status-h: 22px;             /* 状态栏 */
    --xp-clock-w: 0px;               /* 托盘时钟的宽（主题伴侣给 html 加上 .xp-has-clock 才有） */
    --xp-tray-w: calc(96px + var(--xp-clock-w));   /* 任务栏右边托盘 */
    --xp-frame: 4px;                 /* 窗口左右下的蓝边 */
    --xp-to-h: 24px;                 /* 「收件人：」那一条 */

    /* 对话窗口的位置（电脑） */
    --xp-win-w: min(var(--xp-win-max), calc(100vw - 2 * var(--xp-win-side)));
    --xp-win-l: calc((100vw - var(--xp-win-w)) / 2);
    --xp-win-t: var(--xp-win-gap);
    --xp-win-h: calc(100dvh - var(--xp-tb-h) - 2 * var(--xp-win-gap));
    --xp-win-r: calc(var(--xp-win-l) + var(--xp-win-w));
    --xp-body-t: calc(var(--xp-win-t) + var(--xp-title-h) + var(--xp-menu-h));    /* 蓝色内框的上沿 */
    --xp-body-b: calc(var(--xp-win-t) + var(--xp-win-h) - var(--xp-frame) - var(--xp-status-h));
    --xp-side-l: calc(var(--xp-win-r) - var(--xp-frame) - var(--xp-side-w));

    --xp-meta: #5B5B5B;              /* 「星野澪 说：」那行灰字（白底 6.6:1） */
    --xp-ink: #000000;

    --mainFontFamily: var(--xp-ui-font);
    --mainFontSize: 12px;

    /* 面板里的控件（shared/st-fixes.css 用） */
    --fx-ink: #000000;
    --fx-meta: #5B5B5B;
    --fx-accent: var(--xp-sel);
    --fx-on-accent: var(--xp-sel-ink);
    --fx-hairline: #ACA899;
    --fx-surface: #FFFFFF;
    --fx-radius: 3px;

    /* 世界书 / 预设条目（shared/entry-states.css 用）：开 = 绿边，常驻 = 蓝边，关 = 灰底灰字 */
    --st-entry-on: #3C9A1C;
    --st-entry-constant: #215DC6;
    --st-entry-off: #ACA899;
    --st-entry-off-bg: linear-gradient(#F2F1EA, #F2F1EA);
    --st-entry-off-style: solid;
    --st-entry-off-title-color: #6D6D6D;
    --st-entry-off-title-style: normal;
    --st-entry-bar: 3px;
    --st-entry-radius: 3px;
}

/* ================================================================
 * 桌面
 * ================================================================ */
body {
    background: var(--xp-art-wallpaper) center bottom / cover no-repeat, var(--xp-desktop);
    font-family: var(--xp-ui-font);
    font-size: 12px;
    color: var(--xp-ink);
}

/* 酒馆自己的背景图：默认藏起来露出壁纸；想用自己的壁纸，在「更改对话背景」里选一张，再把下面这行的 none 改成 block */
#bg1,
#bg_custom {
    display: none;
}

/* XP 的滚动条：浅蓝滑块、圆角箭头按钮 */
@media (hover: hover) {
    ::-webkit-scrollbar { width: 17px; height: 17px; }
    ::-webkit-scrollbar-corner { background: var(--xp-face); }
    ::-webkit-scrollbar-track:vertical { background-image: var(--xp-css-scroll-background); }
    ::-webkit-scrollbar-track:horizontal { background-image: var(--xp-css-scroll-background-horizontal); }
    ::-webkit-scrollbar-thumb {
        background-position: center;
        background-repeat: no-repeat;
        background-color: var(--xp-thumb);
        background-size: 7px;
        border: 1px solid #FFFFFF;
        border-radius: 2px;
        box-shadow: var(--xp-thumb-shadow);
    }
    ::-webkit-scrollbar-thumb:vertical { background-image: var(--xp-css-scroll-thumb); }
    ::-webkit-scrollbar-thumb:horizontal { background-size: 8px; background-image: var(--xp-css-scroll-thumb-horizontal); }
    ::-webkit-scrollbar-button:vertical:start { height: 17px; background-image: var(--xp-css-scroll-arrow-up); }
    ::-webkit-scrollbar-button:vertical:end { height: 17px; background-image: var(--xp-css-scroll-arrow-down); }
    ::-webkit-scrollbar-button:horizontal:start { width: 17px; background-image: var(--xp-css-scroll-arrow-left); }
    ::-webkit-scrollbar-button:horizontal:end { width: 17px; background-image: var(--xp-css-scroll-arrow-right); }
    /* 酒馆在一些地方另设了细滚动条，统一回 XP 的 */
    * { scrollbar-width: auto; scrollbar-color: auto; }
}

/* ================================================================
 * 电脑
 * ================================================================ */
@media screen and (min-width: 1001px) {

    /* 任务栏画在 body 的背景上（最底层），这样聊天区里的「星野澪 - 对话」按钮才能压在它上面 */
    body {
        background:
            var(--xp-tray-grad) right 0 bottom 0 / var(--xp-tray-w) var(--xp-tb-h) no-repeat,
            linear-gradient(var(--xp-tray-edge), var(--xp-tray-edge)) right var(--xp-tray-w) bottom 0 / 1px var(--xp-tb-h) no-repeat,
            var(--xp-tb-grad) 0 100% / 100% var(--xp-tb-h) no-repeat,
            var(--xp-art-wallpaper) center bottom / cover no-repeat,
            var(--xp-desktop);
    }

    /* ---------------- 对话窗口的框：标题栏 + 菜单栏 + 深蓝内框 + 右边任务窗格 + 状态栏 ----------------
     * 用 #top-bar 画（它本来是顶栏，空的），压在聊天区下面 */
    #top-bar {
        position: fixed;
        left: var(--xp-win-l);
        top: var(--xp-win-t);
        width: var(--xp-win-w);
        height: var(--xp-win-h);
        margin: 0;
        z-index: 29;
        border-radius: 8px 8px 0 0;
        backdrop-filter: none;
        -webkit-backdrop-filter: none;
        background-color: var(--xp-body-blue);
        background-repeat: no-repeat;
        background-image:
            var(--xp-art-chevUp), var(--xp-art-chevUp),
            linear-gradient(var(--xp-side-box), var(--xp-side-box)), var(--xp-side-head),
            linear-gradient(var(--xp-side-box), var(--xp-side-box)), var(--xp-side-head),
            var(--xp-art-messenger),
            var(--xp-css-close), var(--xp-css-maximize), var(--xp-css-minimize),
            var(--xp-title-grad),
            linear-gradient(var(--xp-face), var(--xp-face)),
            linear-gradient(var(--xp-face), var(--xp-face)),
            var(--xp-art-grip),
            var(--xp-side-bg);
        background-size:
            16px 16px, 16px 16px,
            calc(var(--xp-side-w) - 16px) 166px, calc(var(--xp-side-w) - 16px) 24px,
            calc(var(--xp-side-w) - 16px) 148px, calc(var(--xp-side-w) - 16px) 24px,
            16px 16px,
            21px 21px, 21px 21px, 21px 21px,
            100% var(--xp-title-h),
            100% var(--xp-menu-h),
            100% var(--xp-status-h),
            12px 12px,
            var(--xp-side-w) calc(var(--xp-win-h) - var(--xp-title-h) - var(--xp-menu-h) - var(--xp-status-h) - var(--xp-frame));
        background-position:
            right calc(var(--xp-frame) + 12px) top calc(var(--xp-title-h) + var(--xp-menu-h) + 12px),
            right calc(var(--xp-frame) + 12px) top calc(var(--xp-title-h) + var(--xp-menu-h) + 214px),
            right calc(var(--xp-frame) + 8px) top calc(var(--xp-title-h) + var(--xp-menu-h) + 32px),
            right calc(var(--xp-frame) + 8px) top calc(var(--xp-title-h) + var(--xp-menu-h) + 8px),
            right calc(var(--xp-frame) + 8px) top calc(var(--xp-title-h) + var(--xp-menu-h) + 234px),
            right calc(var(--xp-frame) + 8px) top calc(var(--xp-title-h) + var(--xp-menu-h) + 210px),
            8px 7px,
            right 6px top 5px, right 29px top 5px, right 52px top 5px,
            0 0,
            0 var(--xp-title-h),
            0 calc(100% - var(--xp-frame)),
            right var(--xp-frame) bottom calc(var(--xp-frame) + 1px),
            right var(--xp-frame) top calc(var(--xp-title-h) + var(--xp-menu-h));
        box-shadow: var(--xp-frame-shadow), 0 0 0 1px rgba(0, 0, 0, 0.05);
        font: 12px/var(--xp-menu-h) var(--xp-ui-font);
        color: #000;
    }

    /* 标题栏的字：没有角色消息时就是「对话」，有了换成「星野澪 - 对话」（见下面 .mes::before） */
    #top-bar::before {
        content: '对话';
        position: absolute;
        left: 29px;
        top: 0;
        height: var(--xp-title-h);
        font: 700 13px/31px var(--xp-title-font);
        color: var(--xp-title-ink);
        text-shadow: 1px 1px var(--xp-title-shadow);
        letter-spacing: 0.2px;
    }

    /* 菜单栏 */
    #top-bar::after {
        content: '文件(F)\2003编辑(E)\2003查看(V)\2003动作(A)\2003帮助(H)';
        position: absolute;
        left: 4px;
        right: 4px;
        top: var(--xp-title-h);
        height: var(--xp-menu-h);
        padding-left: 6px;
        box-sizing: border-box;
        border-bottom: 1px solid #FFFFFF;
        box-shadow: 0 1px 0 #ACA899 inset, 0 -1px 0 #D6D2C2 inset;
        font: 12px/var(--xp-menu-h) var(--xp-ui-font);
        color: #000;
        white-space: pre;
    }

    /* ---------------- 聊天区 = 窗口里左边那一栏 ---------------- */
    #sheld {
        position: fixed;
        left: calc(var(--xp-win-l) + var(--xp-frame)) !important;
        top: calc(var(--xp-body-t) + var(--xp-to-h)) !important;
        width: calc(var(--xp-win-w) - 2 * var(--xp-frame) - var(--xp-side-w)) !important;
        height: calc(var(--xp-body-b) - var(--xp-body-t) - var(--xp-to-h)) !important;
        max-height: none;
        margin: 0;
        padding: 0 5px 5px 4px;
        box-sizing: border-box;
        overflow: visible;
        z-index: 30;
    }

    #sheldheader { display: none; }

    /* 状态栏的字：平时是 Messenger 那句老提醒，生成时换成「正在输入消息」 */
    #sheld::after {
        content: var(--xp-status);
        position: absolute;
        left: 0;
        top: 100%;
        width: 100%;
        height: var(--xp-status-h);
        padding-left: 6px;
        box-sizing: border-box;
        font: 12px/var(--xp-status-h) var(--xp-ui-font);
        color: #000;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    body[data-generating] #sheld::after {
        content: var(--xp-typing);
        padding-left: 26px;
        background: var(--xp-art-messenger) no-repeat 6px center / 16px 16px;
    }

    /* 消息记录：白色圆角框（底下接着工具条） */
    #chat {
        flex: 1;
        background: #FFFFFF;
        border: 1px solid var(--xp-box-edge);
        border-bottom: 0;
        border-radius: 5px 5px 0 0;
        backdrop-filter: none;
        -webkit-backdrop-filter: none;
        padding: 6px 4px 10px 8px;
        overflow-y: scroll;
    }

    /* 工具条（阻止 / 字体 / 表情符号那一行）+ 输入框 */
    #form_sheld {
        position: relative;
        width: 100%;
        margin: 0;
        padding: 36px 0 0;
        background:
            linear-gradient(var(--xp-strip), var(--xp-strip)) 0 0 / 100% 32px no-repeat;
        border: 1px solid var(--xp-box-edge);
        border-top: 0;
        border-radius: 0 0 5px 5px;
        box-shadow: 0 4px 0 var(--xp-body-blue) inset;
        background-color: transparent;
    }

    /* 工具条下面那道深蓝缝，隔开输入框 */
    #form_sheld::after {
        content: '';
        position: absolute;
        left: -1px;
        right: -1px;
        top: 32px;
        height: 4px;
        background: var(--xp-body-blue);
        pointer-events: none;
    }

    #send_form {
        min-height: 84px;
        margin: 0 -1px -1px;
        padding: 0;
        background: #FFFFFF;
        border: 1px solid var(--xp-box-edge);
        border-radius: 5px;
        backdrop-filter: none;
        -webkit-backdrop-filter: none;
    }

    #nonQRFormItems {
        align-items: stretch;
        padding: 4px 6px 6px 6px;
    }

    #send_textarea {
        min-height: 72px;
        padding: 2px 4px;
        font: var(--xp-chat-size) / 1.5 var(--xp-chat-font);
        color: #000;
        background: transparent;
        border: 0;
        outline: none;
        box-shadow: none;
    }

    #send_textarea::placeholder {
        color: #8C8C8C;
        text-align: left;
    }

    /* 没连上 API 时酒馆把发送按钮藏起来；Messenger 里这时是一个灰掉的「发送(S)」 */
    #rightSendForm::after {
        content: '发送(S)';
        display: none;
        align-self: center;
        width: 64px;
        height: 40px;
        box-sizing: border-box;
        border: 1px solid #C9C7BA;
        border-radius: 3px;
        background: #F5F4EA;
        font: 12px/38px var(--xp-ui-font);
        color: #ACA899;
        text-align: center;
    }

    #rightSendForm:has(#send_but.displayNone):not(:has(#mes_stop[style*="flex"]))::after {
        display: block;
    }

    /* 工具条里的按钮：≡ = 动作、魔杖 = 表情符号 */
    #leftSendForm {
        position: absolute;
        left: 6px;
        top: -35px;
        height: 32px;
        display: flex;
        align-items: center;
        gap: 4px;
        width: auto;
    }

    #leftSendForm > div,
    #extensionsMenuButton {
        display: flex !important;
        align-items: center;
        gap: 4px;
        width: auto !important;
        height: 26px;
        padding: 0 8px 0 30px;
        border: 1px solid transparent;
        border-radius: 3px;
        font: 12px/24px var(--xp-ui-font) !important;
        color: #000 !important;
        opacity: 1 !important;
        background: no-repeat 6px center / 20px 20px;
        cursor: default;
    }

    #leftSendForm > div:hover,
    #extensionsMenuButton:hover {
        border-color: #CECECE #8E8F8F #8E8F8F #CECECE;
        background-color: #F0F4FD;
    }

    #leftSendForm > div::before,
    #extensionsMenuButton::before {
        font: inherit !important;
    }

    #options_button { background-image: var(--xp-art-actions) !important; }
    #options_button::before { content: '动作'; }
    #extensionsMenuButton { background-image: var(--xp-art-smiley) !important; }
    #extensionsMenuButton::before { content: '表情符号 \25BE'; }
    #extensionsMenuButton > * { display: none; }

    /* 发送按钮：输入框右边那个大按钮「发送(S)」 */
    #rightSendForm {
        align-items: stretch;
        gap: 4px;
    }

    #rightSendForm > div {
        opacity: 1;
    }

    #send_but,
    #mes_stop {
        width: 64px !important;
        min-height: 40px;
        align-self: center;
        display: flex;
        align-items: center;
        justify-content: center;
        border: 1px solid var(--xp-btn-edge);
        border-radius: 3px;
        background: linear-gradient(180deg, #FFFFFF 0%, #ECEBE5 86%, #D8D0C4 100%);
        font: 12px/1 var(--xp-ui-font) !important;
        color: #000 !important;
        cursor: default;
    }

    #send_but::before { content: '发送(S)'; font: inherit !important; }
    #mes_stop > i { display: none; }
    #mes_stop::before { content: '停止'; }

    #send_but:hover,
    #mes_stop:hover {
        box-shadow: inset -1px 1px #FFF0CF, inset 1px 2px #FDD889, inset -2px 2px #FBC761, inset 2px -2px #E5A01A;
    }

    #send_but:active,
    #mes_stop:active {
        background: linear-gradient(180deg, #CDCAC3 0%, #E3E3DB 8%, #E5E5DE 94%, #F2F2F1 100%);
    }

    #mes_continue,
    #mes_impersonate {
        align-self: center;
        width: 24px;
        height: 24px;
        font-size: 14px !important;
        color: var(--xp-link) !important;
    }

    /* ---------------- 最新那条角色消息：把名字送到标题栏、收件人、任务栏，头像送到右边「摄像头」 ----------------
     * attr(ch_name) 只能从 .mes 自己身上读，而 .mes 只有 ::before ::after 两个，
     * 所以标题栏和「收件人」合成一个两行的 ::before：第一行缩进到小图标后面，第二行落在收件人那一条 */
    #chat .mes[is_user="false"][is_system="false"]:not(:has(~ .mes[is_user="false"][is_system="false"]))::before,
    #chat .mes[is_user="false"][is_system="false"]:not(:has(~ .mes[is_user="false"][is_system="false"]))::after {
        position: fixed;
        pointer-events: none;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    #chat .mes[is_user="false"][is_system="false"]:not(:has(~ .mes[is_user="false"][is_system="false"]))::before {
        --lh: calc((var(--xp-title-h) + var(--xp-menu-h) + var(--xp-to-h) / 2 - var(--xp-title-h) / 2) / 2);   /* 两行中心相距两行高 */
        content: attr(ch_name) var(--xp-title-suffix) '\A\A' var(--xp-to) '\2002' attr(ch_name);
        white-space: pre;
        left: calc(var(--xp-win-l) + var(--xp-frame) + 8px);
        top: calc(var(--xp-win-t) + var(--xp-title-h) / 2 + 0.5px - var(--lh) / 2);
        width: calc(var(--xp-win-w) - 2 * var(--xp-frame) - var(--xp-side-w) - 16px);
        text-indent: 17px;
        font: 700 13px/var(--lh) var(--xp-title-font);
        letter-spacing: 0.2px;
        /* 第一行白（标题栏），第二行浅蓝（收件人） */
        background: linear-gradient(var(--xp-title-ink) 0 calc(var(--lh) * 1.5), var(--xp-to-ink) 0) no-repeat;
        -webkit-background-clip: text;
        background-clip: text;
        color: transparent;
        filter: drop-shadow(1px 1px 0 var(--xp-title-shadow));
        z-index: 31;
    }

    body:has(#chat .mes[is_user="false"][is_system="false"]) #top-bar::before {
        content: none;
    }

    /* 任务栏上的按钮「星野澪 - 对话」（按下去的样子 = 当前窗口） */
    #chat .mes[is_user="false"][is_system="false"]:not(:has(~ .mes[is_user="false"][is_system="false"]))::after {
        content: attr(ch_name) var(--xp-title-suffix);
        left: 110px;
        top: calc(100dvh - var(--xp-tb-h) + 3px);
        width: 160px;
        height: 22px;
        box-sizing: border-box;
        padding: 0 8px 0 27px;
        border-radius: 2px;
        background: var(--xp-art-messenger) no-repeat 7px center / 16px 16px, var(--xp-task-btn);
        box-shadow: inset 0 0 1px 1px rgba(0, 0, 0, 0.2), inset 1px 0 1px rgba(0, 0, 0, 0.7);
        font: 12px/22px var(--xp-ui-font);
        color: var(--xp-task-ink);
        z-index: 3007;
    }

    /* 「摄像头」里的头像 */
    #chat .mes[is_user="false"][is_system="false"]:not(:has(~ .mes[is_user="false"][is_system="false"])) .mesAvatarWrapper .avatar {
        display: block !important;
        position: fixed;
        left: calc(var(--xp-side-l) + 20px);
        top: calc(var(--xp-body-t) + 42px);
        width: calc(var(--xp-side-w) - 40px) !important;
        height: calc(var(--xp-side-w) - 40px) !important;
        margin: 0;
        padding: 3px;
        background: #FFFFFF;
        border: 1px solid var(--xp-input-edge);
        border-radius: 0;
        z-index: 31;
    }

    #chat .mes[is_user="false"][is_system="false"]:not(:has(~ .mes[is_user="false"][is_system="false"])) .mesAvatarWrapper .avatar img {
        width: 100%;
        height: 100%;
        border-radius: 0;
        object-fit: cover;
    }

    /* ---------------- 桌面 + 任务栏 + 右边「我想…」的链接 ---------------- */
    #top-settings-holder {
        position: fixed;
        inset: 0;
        width: 100%;
        height: 100%;
        margin: 0;
        display: block;
        z-index: 3005;
        pointer-events: none;
    }

    /* 组标题的字 */
    #top-settings-holder::after {
        content: '摄像头';
        position: absolute;
        left: calc(var(--xp-side-l) + 20px);
        top: calc(var(--xp-body-t) + 8px);
        font: 700 12px/24px var(--xp-ui-font);
        color: var(--xp-link);
        pointer-events: none;
    }

    #sys-settings-button::before {
        content: '我想...';
        position: absolute;
        left: calc(var(--xp-side-l) + 20px);
        top: calc(var(--xp-body-t) + 210px);
        font: 700 12px/24px var(--xp-ui-font);
        color: var(--xp-link);
        pointer-events: none;
    }

    /* 每个面板按钮的位置、图标、名字（.drawer 上定义，按钮和窗口都能继承）
     *   --x --y --w --h：桌面图标 / 链接的位置大小
     *   --xp-label：图标下面的字　--xp-ico：图标
     *   --xp-dlg：窗口标题　--xp-dlg-w / -l / -t：窗口大小位置 */
    #top-settings-holder {
        --xp-dlg-w: 720px;
        --xp-dlg-l: calc((100vw - var(--xp-dlg-w)) / 2);
        --xp-dlg-t: 56px;
    }

    #top-settings-holder > .drawer {
        position: static;
        display: block;
        width: auto;
    }

    #top-settings-holder > .drawer { --xp-dlg-l: calc((100vw - var(--xp-dlg-w)) / 2); }
    #user-settings-button { --y: 10px; --xp-label: '我的电脑'; --xp-ico: var(--xp-art-icoComputer); --xp-dlg: '用户设置'; --xp-dlg-w: min(960px, calc(100vw - 120px)); }
    #WI-SP-button { --y: 86px; --xp-label: '我的文档'; --xp-ico: var(--xp-art-icoDocuments); --xp-dlg: '世界书'; --xp-dlg-w: min(1100px, calc(100vw - 120px)); }
    #sys-settings-button { --y: 162px; --xp-label: '网上邻居'; --xp-ico: var(--xp-art-icoNetwork); --xp-dlg: 'API 连接'; }
    #extensions-settings-button { --y: 238px; --xp-label: '控制面板'; --xp-ico: var(--xp-art-icoControl); --xp-dlg: '扩展'; --xp-dlg-w: min(900px, calc(100vw - 120px)); }
    #persona-management-button { --y: calc(var(--xp-body-t) + 246px); --xp-label: '编辑我的个人资料'; --xp-ico: var(--xp-art-personCard); --xp-dlg: '我的个人资料（人设）'; --xp-dlg-w: min(900px, calc(100vw - 120px)); }
    #backgrounds-button { --y: calc(var(--xp-body-t) + 280px); --xp-label: '更改对话背景'; --xp-ico: var(--xp-art-photoFolder); --xp-dlg: '显示 属性'; --xp-dlg-w: min(900px, calc(100vw - 120px)); }
    #top-settings-holder > #ai-config-button { --y: calc(var(--xp-body-t) + 314px); --xp-label: '调整回复方式'; --xp-ico: var(--xp-art-gear); --xp-dlg: '回复方式（预设）'; --xp-dlg-w: 420px; --xp-dlg-l: 96px; --xp-dlg-t: 12px; }
    #advanced-formatting-button { --y: calc(var(--xp-body-t) + 348px); --xp-label: '设置消息格式'; --xp-ico: var(--xp-art-fontA); --xp-dlg: '消息格式（高级格式）'; --xp-dlg-w: min(960px, calc(100vw - 120px)); }

    /* 桌面上的四个 */
    #user-settings-button, #WI-SP-button, #sys-settings-button, #extensions-settings-button {
        --x: 6px; --w: 74px; --h: 70px;
    }

    /* 任务窗格「我想…」里的四个 */
    #persona-management-button, #backgrounds-button, #ai-config-button, #advanced-formatting-button {
        --x: calc(var(--xp-side-l) + 12px); --w: calc(var(--xp-side-w) - 24px); --h: 32px;
    }

    /* 画：图标 + 字。按钮本身是盖在上面的透明块（打开时它要挪去当关闭按钮，画留在原地） */
    #user-settings-button::after, #WI-SP-button::after, #sys-settings-button::after, #extensions-settings-button::after,
    #persona-management-button::after, #backgrounds-button::after, #ai-config-button::after, #advanced-formatting-button::after {
        content: var(--xp-label);
        position: absolute;
        left: var(--x);
        top: var(--y);
        width: var(--w);
        height: var(--h);
        box-sizing: border-box;
        background: var(--xp-ico) no-repeat;
        pointer-events: none;
    }

    #user-settings-button::after, #WI-SP-button::after, #sys-settings-button::after, #extensions-settings-button::after {
        padding-top: 38px;
        background-position: center 2px;
        background-size: 32px 32px;
        font: 12px/14px var(--xp-ui-font);
        color: #FFFFFF;
        text-align: center;
        text-shadow: 1px 1px 0 #000, 1px 1px 2px #000;
    }

    /* 选中（鼠标移上去 / 窗口开着）：字变蓝底白字，图标蒙一层蓝 */
    #top-settings-holder > .drawer:is(#user-settings-button, #WI-SP-button, #sys-settings-button, #extensions-settings-button):is(:has(> .drawer-toggle:hover), :has(.openIcon))::after {
        background-image: linear-gradient(rgba(11, 97, 255, 0.45), rgba(11, 97, 255, 0.45)), var(--xp-ico);
        background-size: 32px 32px, 32px 32px;
        background-position: center 2px, center 2px;
        background-blend-mode: normal;
        text-shadow: none;
        -webkit-mask: none;
    }

    #top-settings-holder > .drawer:is(#user-settings-button, #WI-SP-button, #sys-settings-button, #extensions-settings-button):is(:has(> .drawer-toggle:hover), :has(.openIcon))::after {
        color: #FFFFFF;
        background-color: transparent;
    }

    #persona-management-button::after, #backgrounds-button::after, #ai-config-button::after, #advanced-formatting-button::after {
        padding: 1px 0 0 23px;
        background-position: 2px 1px;
        background-size: 16px 16px;
        font: 12px/15px var(--xp-ui-font);
        color: var(--xp-link);
    }

    #top-settings-holder > .drawer:is(#persona-management-button, #backgrounds-button, #ai-config-button, #advanced-formatting-button):has(> .drawer-toggle:hover)::after {
        color: var(--xp-link-hover);
        text-decoration: underline;
    }

    #top-settings-holder .drawer-toggle {
        position: absolute;
        left: var(--x);
        top: var(--y);
        width: var(--w);
        height: var(--h);
        pointer-events: auto;
        display: block;
    }

    #top-settings-holder .drawer-icon {
        display: block;
        position: relative;
        width: 100%;
        height: 100%;
        padding: 0;
        opacity: 1 !important;
        font-size: 0 !important;
        background: transparent;
        cursor: default;
    }

    #top-settings-holder .drawer-icon:not(#rightNavDrawerIcon)::before {
        content: none !important;
    }

    /* ---------------- 任务栏：开始按钮 = 角色 ---------------- */
    /* 托盘：音量、Messenger 小人 */
    #rightNavHolder::after {
        content: var(--xp-clock, '');
        position: absolute;
        right: 0;
        top: calc(100dvh - var(--xp-tb-h) + 7px);
        width: var(--xp-tray-w);
        height: 16px;
        padding-right: 12px;
        box-sizing: border-box;
        background:
            var(--xp-art-messenger) no-repeat right calc(36px + var(--xp-clock-w)) top 0 / 16px 16px,
            var(--xp-art-speaker) no-repeat right calc(14px + var(--xp-clock-w)) top 0 / 16px 16px;
        font: 12px/16px var(--xp-ui-font);
        color: var(--xp-tray-ink);
        text-align: right;
        white-space: nowrap;
        pointer-events: none;
    }

    #rightNavHolder .drawer-toggle {
        left: 0;
        top: calc(100dvh - var(--xp-tb-h));
        width: 99px;
        height: var(--xp-tb-h);
        z-index: 2;
    }

    #rightNavHolder .drawer-icon {
        border-radius: 0 12px 12px 0;
        background:
            var(--xp-art-flag) no-repeat 8px center / 22px 24px,
            radial-gradient(ellipse 80% 70% at 40% 0%, rgba(255, 255, 255, 0.38), rgba(255, 255, 255, 0) 60%),
            linear-gradient(180deg, #3A9A3A 0%, #4FC34D 6%, #3EAD3B 14%, #37A034 50%, #2F8F2E 86%, #2A7F29 96%, #1F5F1F 100%);
        box-shadow: inset -2px 0 2px rgba(0, 0, 0, 0.35), inset 0 1px 1px rgba(255, 255, 255, 0.4), 2px 0 3px rgba(0, 0, 0, 0.35);
    }

    #rightNavHolder .drawer-icon::before {
        content: '开始';
        position: absolute;
        left: 36px;
        top: 0;
        font: italic 400 17px/30px SimSun, '宋体', 'Songti SC', serif !important;   /* 中文版 XP：宋体斜体，不加粗（英文版是粗斜的 start） */
        color: #FFFFFF;
        text-shadow: 1px 1px 1px rgba(0, 0, 0, 0.7);
        letter-spacing: 2px;
    }

    #rightNavHolder .drawer-icon:hover {
        filter: brightness(1.08);
    }

    #rightNavHolder .drawer-icon.openIcon {
        filter: brightness(0.85);
    }

    /* ---------------- 打开的面板：XP 窗口（蓝标题栏 + 米色底） ---------------- */
    #top-settings-holder .drawer-content {
        pointer-events: auto;
        z-index: 10;
        position: fixed;
        left: var(--xp-dlg-l);
        top: var(--xp-dlg-t);
        right: auto;
        width: var(--xp-dlg-w);
        min-width: 0;
        max-width: none;
        max-height: calc(100dvh - var(--xp-tb-h) - var(--xp-dlg-t) - 20px);
        height: auto;
        margin: 0;
        padding: 0 10px 10px;
        box-sizing: border-box;
        background: var(--xp-face);
        border: 0;
        border-radius: 8px 8px 0 0;
        box-shadow: var(--xp-frame-shadow), 4px 4px 12px rgba(0, 0, 0, 0.35);
        backdrop-filter: none;
        -webkit-backdrop-filter: none;
        color: #000;
        font: 12px/1.4 var(--xp-ui-font);
    }

    /* 标题栏：贴在窗口顶上，跟着滚动不走 */
    #top-settings-holder .drawer-content::before {
        content: var(--xp-dlg);
        position: sticky;
        top: 0;
        display: block;
        flex: none;
        margin: 0 -10px 8px;
        padding: 0 80px 0 28px;
        height: var(--xp-title-h);
        border-radius: 8px 8px 0 0;
        background: var(--xp-ico) no-repeat 7px 7px / 16px 16px, var(--xp-css-close) no-repeat right 6px top 5px / 21px 21px, var(--xp-title-grad);
        box-shadow: var(--xp-title-edge);
        font: 700 13px/31px var(--xp-title-font);
        color: var(--xp-title-ink);
        text-shadow: 1px 1px var(--xp-title-shadow);
        z-index: 20;
    }

    /* 打开着的面板：桌面图标 / 链接本身挪到标题栏的红 × 上，点它就关 */
    #top-settings-holder .drawer-icon.openIcon {
        font-size: 0 !important;
    }

    #top-settings-holder .drawer:has(> .drawer-content.openDrawer:not(.fillRight)) > .drawer-toggle {
        position: fixed;
        left: calc(var(--xp-dlg-l) + var(--xp-dlg-w) - 27px);
        top: calc(var(--xp-dlg-t) + 5px);
        width: 21px;
        height: 21px;
        z-index: 3010;
    }

    #top-settings-holder .drawer:has(> .drawer-content.openDrawer:not(.fillRight)) > .drawer-toggle .drawer-icon {
        background: var(--xp-css-close) no-repeat center / 21px 21px;
    }

    #top-settings-holder .drawer:has(> .drawer-content.openDrawer:not(.fillRight)) > .drawer-toggle .drawer-icon:hover {
        background-image: var(--xp-css-close-hover);
    }

    #top-settings-holder .drawer:has(> .drawer-content.openDrawer:not(.fillRight)) > .drawer-toggle .drawer-icon:active {
        background-image: var(--xp-css-close-active);
    }

    #top-settings-holder .drawer:has(> .drawer-content.openDrawer:not(.fillRight)) > .drawer-toggle .drawer-icon::before {
        display: none;
    }

    /* 预设：左边一个高窗口 */
    #left-nav-panel.drawer-content {
        height: calc(100dvh - var(--xp-tb-h) - 24px);
        max-height: none;
        display: none;
        flex-direction: column;
    }

    #left-nav-panel.drawer-content.openDrawer { display: flex; }

    #left-nav-panel > #clickSlidersTips,
    #left-nav-panel > .topRightInset {
        top: 40px;
    }

    /* ---------------- 消息：「星野澪 说：」一行灰字，下面正文缩进 ---------------- */
    #chat .mes {
        padding: 2px 0 6px;
        border: 0;
        background: transparent;
    }

    #chat .mes .mesAvatarWrapper {
        display: none;
    }

    #chat .mes[is_user="false"][is_system="false"]:not(:has(~ .mes[is_user="false"][is_system="false"])) .mesAvatarWrapper {
        display: block;
        width: 0;
        height: 0;
        overflow: visible;
        padding: 0;
        margin: 0;
    }

    #chat .mes .mes_block {
        padding: 0;
    }

    #chat .mes .ch_name {
        min-height: 0;
        font: 12px/20px var(--xp-ui-font);
    }

    #chat .mes .name_text {
        font: 12px/20px var(--xp-ui-font);
        color: var(--xp-meta);
    }

    #chat .mes .name_text::after {
        content: var(--xp-says);
    }

    #chat .mes .mes_text {
        padding: 0 8px 0 15px;
        font: var(--xp-chat-size) / var(--xp-chat-line) var(--xp-chat-font);
        color: var(--xp-ink);
    }

    #chat .mes .mes_text p {
        margin: 0 0 0.35em;
    }

    #chat .mes .mes_text em,
    #chat .mes .mes_text q {
        color: inherit;
    }
}

/* ================================================================
 * 手机：对话窗口最大化，占满任务栏以上的整屏
 *   菜单栏就是「我想…」那四项：资料 = 人设　背景 = 背景　预设 = 预设　格式 = 高级格式
 *   任务栏：开始 = 角色，旁边快速启动四个小图标：我的电脑 = 用户设置　我的文档 = 世界书　网上邻居 = API　控制面板 = 扩展
 *   打开的面板也是最大化的窗口，右上角 × 关闭
 * ================================================================ */
@media screen and (max-width: 1000px) {
    :root {
        --xp-tb-h: 36px;
        --xp-menu-h: 28px;
        --xp-to-h: 22px;
        --topBarBlockSize: calc(var(--xp-title-h) + var(--xp-menu-h) + var(--xp-to-h));
        --xp-m-ql: 82px;             /* 快速启动从哪里开始（开始按钮右边） */
        --xp-m-cell: 36px;           /* 快速启动每格宽 */
    }

    body {
        background:
            var(--xp-tray-grad) right 0 bottom 0 / var(--xp-tray-w) var(--xp-tb-h) no-repeat,
            linear-gradient(var(--xp-tray-edge), var(--xp-tray-edge)) right var(--xp-tray-w) bottom 0 / 1px var(--xp-tb-h) no-repeat,
            var(--xp-tb-grad) 0 100% / 100% var(--xp-tb-h) no-repeat,
            var(--xp-art-wallpaper) center bottom / cover no-repeat,
            var(--xp-desktop);
    }

    /* 窗口框：标题栏（最大化 = 中间是「还原」）、菜单栏、深蓝内框 */
    #top-bar {
        position: fixed;
        left: 0;
        top: 0;
        width: 100%;
        height: calc(100dvh - var(--xp-tb-h));
        margin: 0;
        z-index: 29;
        border-radius: 7px 7px 0 0;
        backdrop-filter: none;
        -webkit-backdrop-filter: none;
        box-shadow: none;
        background-color: var(--xp-body-blue);
        background-repeat: no-repeat;
        background-image:
            var(--xp-art-messenger),
            var(--xp-css-close), var(--xp-css-restore), var(--xp-css-minimize),
            var(--xp-title-grad),
            linear-gradient(var(--xp-face), var(--xp-face));
        background-size: 16px 16px, 21px 21px, 21px 21px, 21px 21px, 100% var(--xp-title-h), 100% var(--xp-menu-h);
        background-position: 7px 7px, right 5px top 5px, right 28px top 5px, right 51px top 5px, 0 0, 0 var(--xp-title-h);
    }

    #top-bar::before {
        content: '对话';
        position: absolute;
        left: 28px;
        top: 0;
        font: 700 13px/31px var(--xp-title-font);
        color: var(--xp-title-ink);
        text-shadow: 1px 1px var(--xp-title-shadow);
    }

    body:has(#chat .mes[is_user="false"][is_system="false"]) #top-bar::before {
        content: none;
    }

    /* 标题 + 收件人（两行，同电脑版的做法） */
    #chat .mes[is_user="false"][is_system="false"]:not(:has(~ .mes[is_user="false"][is_system="false"]))::before {
        --lh: calc((var(--xp-title-h) + var(--xp-menu-h) + var(--xp-to-h) / 2 - var(--xp-title-h) / 2) / 2);
        content: attr(ch_name) var(--xp-title-suffix) '\A\A' var(--xp-to) '\2002' attr(ch_name);
        position: fixed;
        white-space: pre;
        overflow: hidden;
        text-overflow: ellipsis;
        pointer-events: none;
        left: 8px;
        top: calc(var(--xp-title-h) / 2 + 0.5px - var(--lh) / 2);
        width: calc(100vw - 90px);
        text-indent: 20px;
        font: 700 13px/var(--lh) var(--xp-title-font);
        background: linear-gradient(var(--xp-title-ink) 0 calc(var(--lh) * 1.5), var(--xp-to-ink) 0) no-repeat;
        -webkit-background-clip: text;
        background-clip: text;
        color: transparent;
        filter: drop-shadow(1px 1px 0 var(--xp-title-shadow));
        z-index: 31;
    }

    /* 任务栏上的「沈栖 - 对话」 */
    #chat .mes[is_user="false"][is_system="false"]:not(:has(~ .mes[is_user="false"][is_system="false"]))::after {
        content: attr(ch_name) var(--xp-title-suffix);
        position: fixed;
        pointer-events: none;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        left: calc(var(--xp-m-ql) + 4 * var(--xp-m-cell) + 6px);
        top: calc(100dvh - var(--xp-tb-h) + 4px);
        width: calc(100vw - var(--xp-m-ql) - 4 * var(--xp-m-cell) - 6px - var(--xp-tray-w) - 8px);
        height: calc(var(--xp-tb-h) - 7px);
        box-sizing: border-box;
        padding: 0 6px 0 26px;
        border-radius: 2px;
        background: var(--xp-art-messenger) no-repeat 6px center / 16px 16px, var(--xp-task-btn);
        box-shadow: inset 0 0 1px 1px rgba(0, 0, 0, 0.2), inset 1px 0 1px rgba(0, 0, 0, 0.7);
        font: 12px/29px var(--xp-ui-font);
        color: var(--xp-task-ink);
        z-index: 31;
    }

    /* 聊天区 */
    #sheld {
        position: fixed;
        left: 0 !important;
        top: var(--topBarBlockSize) !important;
        width: 100% !important;
        height: calc(100dvh - var(--topBarBlockSize) - var(--xp-tb-h)) !important;
        max-height: none;
        margin: 0;
        padding: 0 3px 3px;
        box-sizing: border-box;
        z-index: 30;
    }

    #sheldheader { display: none; }

    #chat {
        flex: 1;
        background: #FFFFFF;
        border: 1px solid var(--xp-box-edge);
        border-bottom: 0;
        border-radius: 5px 5px 0 0;
        backdrop-filter: none;
        -webkit-backdrop-filter: none;
        padding: 4px var(--xp-m-pad) 8px;
    }

    #form_sheld {
        position: relative;
        width: 100%;
        margin: 0;
        padding: 34px 0 0;
        background: linear-gradient(var(--xp-strip), var(--xp-strip)) 0 0 / 100% 30px no-repeat;
        border: 1px solid var(--xp-box-edge);
        border-top: 0;
        border-radius: 0 0 5px 5px;
    }

    #form_sheld::after {
        content: '';
        position: absolute;
        left: -1px;
        right: -1px;
        top: 30px;
        height: 4px;
        background: var(--xp-body-blue);
        pointer-events: none;
    }

    #send_form {
        margin: 0 -1px -1px;
        padding: 0;
        background: #FFFFFF;
        border: 1px solid var(--xp-box-edge);
        border-radius: 5px;
        backdrop-filter: none;
        -webkit-backdrop-filter: none;
    }

    #nonQRFormItems {
        align-items: stretch;
        padding: 3px 4px 4px 6px;
    }

    #send_textarea {
        min-height: 44px;
        padding: 3px 4px;
        font: 16px/1.4 var(--xp-chat-font);    /* 16px：iPhone 不会自动放大 */
        color: #000;
        background: transparent;
        border: 0;
        outline: none;
        box-shadow: none;
    }

    #send_textarea::placeholder {
        color: #8C8C8C;
        text-align: left;
    }

    #leftSendForm {
        position: absolute;
        left: 4px;
        top: -33px;
        height: 30px;
        display: flex;
        align-items: center;
        gap: 2px;
        width: auto;
    }

    #leftSendForm > div,
    #extensionsMenuButton {
        display: flex !important;
        align-items: center;
        width: auto !important;
        height: 26px;
        padding: 0 8px 0 28px;
        border: 1px solid transparent;
        border-radius: 3px;
        font: 12px/24px var(--xp-ui-font) !important;
        color: #000 !important;
        opacity: 1 !important;
        background: no-repeat 5px center / 20px 20px;
    }

    #leftSendForm > div::before,
    #extensionsMenuButton::before { font: inherit !important; }
    #options_button { background-image: var(--xp-art-actions) !important; }
    #options_button::before { content: '动作'; }
    #extensionsMenuButton { background-image: var(--xp-art-smiley) !important; }
    #extensionsMenuButton::before { content: '表情符号 \25BE'; }
    #extensionsMenuButton > * { display: none; }

    #rightSendForm { align-items: stretch; gap: 4px; }
    #rightSendForm > div { opacity: 1; }

    #send_but,
    #mes_stop,
    #rightSendForm::after {
        width: 58px !important;
        height: 40px;
        align-self: center;
        display: flex;
        align-items: center;
        justify-content: center;
        box-sizing: border-box;
        border: 1px solid var(--xp-btn-edge);
        border-radius: 3px;
        background: linear-gradient(180deg, #FFFFFF 0%, #ECEBE5 86%, #D8D0C4 100%);
        font: 13px/1 var(--xp-ui-font) !important;
        color: #000 !important;
    }

    #send_but::before { content: '发送(S)'; font: inherit !important; }
    #mes_stop > i { display: none; }
    #mes_stop::before { content: '停止'; }

    #rightSendForm::after {
        content: '发送(S)';
        display: none;
        border-color: #C9C7BA;
        background: #F5F4EA;
        color: #ACA899 !important;
    }

    #rightSendForm:has(#send_but.displayNone):not(:has(#mes_stop[style*="flex"]))::after {
        display: flex;
    }

    #mes_continue,
    #mes_impersonate {
        align-self: center;
        font-size: 16px !important;
        color: var(--xp-link) !important;
    }

    /* 消息 */
    #chat .mes {
        padding: 2px 0 6px;
        border: 0;
        background: transparent;
    }

    #chat .mes .mesAvatarWrapper { display: none; }
    #chat .mes .mes_block { padding: 0; }
    #chat .mes .ch_name { min-height: 0; }

    #chat .mes .name_text {
        font: 12px/20px var(--xp-ui-font);
        color: var(--xp-meta);
    }

    #chat .mes .name_text::after { content: var(--xp-says); }

    #chat .mes .mes_text {
        padding: 0 0 0 12px;
        font: calc(var(--xp-chat-size) + 1px) / var(--xp-chat-line) var(--xp-chat-font);
        color: var(--xp-ink);
    }

    #chat .mes .mes_text p { margin: 0 0 0.35em; }

    /* ---------- 菜单栏 + 任务栏上的按钮 ---------- */
    #top-settings-holder {
        position: fixed;
        inset: 0;
        width: 100%;
        height: 100%;
        margin: 0;
        display: block;
        z-index: 3005;
        pointer-events: none;
    }

    #top-settings-holder > .drawer {
        position: static;
        display: block;
        width: auto;
    }

    #persona-management-button { --x: 2px; --w: 66px; --xp-label: '资料(P)'; --xp-dlg: '我的个人资料（人设）'; --xp-ico: var(--xp-art-personCard); }
    #backgrounds-button { --x: 68px; --w: 62px; --xp-label: '背景(B)'; --xp-dlg: '显示 属性'; --xp-ico: var(--xp-art-icoDisplay); }
    #ai-config-button { --x: 130px; --w: 62px; --xp-label: '预设(R)'; --xp-dlg: '回复方式（预设）'; --xp-ico: var(--xp-art-gear); }
    #advanced-formatting-button { --x: 192px; --w: 62px; --xp-label: '格式(O)'; --xp-dlg: '消息格式（高级格式）'; --xp-ico: var(--xp-art-fontA); }

    #persona-management-button, #backgrounds-button, #ai-config-button, #advanced-formatting-button {
        --y: calc(var(--xp-title-h) + 1px);
        --h: calc(var(--xp-menu-h) - 2px);
    }

    #user-settings-button { --x: calc(var(--xp-m-ql) + 0 * var(--xp-m-cell)); --xp-ico: var(--xp-art-icoComputer); --xp-dlg: '用户设置'; }
    #WI-SP-button { --x: calc(var(--xp-m-ql) + 1 * var(--xp-m-cell)); --xp-ico: var(--xp-art-icoDocuments); --xp-dlg: '世界书'; }
    #sys-settings-button { --x: calc(var(--xp-m-ql) + 2 * var(--xp-m-cell)); --xp-ico: var(--xp-art-icoNetwork); --xp-dlg: 'API 连接'; }
    #extensions-settings-button { --x: calc(var(--xp-m-ql) + 3 * var(--xp-m-cell)); --xp-ico: var(--xp-art-icoControl); --xp-dlg: '扩展'; }

    #user-settings-button, #WI-SP-button, #sys-settings-button, #extensions-settings-button {
        --y: calc(100dvh - var(--xp-tb-h) + 3px);
        --w: var(--xp-m-cell);
        --h: calc(var(--xp-tb-h) - 6px);
    }

    #rightNavHolder { --x: 0px; --y: calc(100dvh - var(--xp-tb-h)); --w: 78px; --h: var(--xp-tb-h); }

    #top-settings-holder .drawer-toggle {
        position: absolute;
        left: var(--x);
        top: var(--y);
        width: var(--w);
        height: var(--h);
        pointer-events: auto;
        display: block;
    }

    #top-settings-holder .drawer-icon {
        display: block;
        position: relative;
        width: 100%;
        height: 100%;
        padding: 0;
        opacity: 1 !important;
        font-size: 0 !important;
        background: transparent no-repeat center;
        border-radius: 3px;
    }

    #top-settings-holder .drawer-icon:not(#rightNavDrawerIcon)::before {
        content: none !important;
    }

    /* 菜单项：字；打开时蓝底白字（XP 菜单的选中色） */
    #persona-management-button .drawer-icon::after,
    #backgrounds-button .drawer-icon::after,
    #ai-config-button .drawer-icon::after,
    #advanced-formatting-button .drawer-icon::after {
        content: var(--xp-label);
        display: block;
        font: 13px/26px var(--xp-ui-font);
        color: #000;
        text-align: center;
    }

    #persona-management-button .drawer-icon.openIcon,
    #backgrounds-button .drawer-icon.openIcon,
    #ai-config-button .drawer-icon.openIcon,
    #advanced-formatting-button .drawer-icon.openIcon {
        background-color: var(--xp-sel);
        border-radius: 0;
    }

    #top-settings-holder .drawer-icon.openIcon::after { color: var(--xp-sel-ink); }

    /* 快速启动：小图标，按下去像凹进去 */
    #user-settings-button .drawer-icon,
    #WI-SP-button .drawer-icon,
    #sys-settings-button .drawer-icon,
    #extensions-settings-button .drawer-icon {
        background-image: var(--xp-ico);
        background-size: 22px 22px;
    }

    #user-settings-button .drawer-icon:active,
    #WI-SP-button .drawer-icon:active,
    #sys-settings-button .drawer-icon:active,
    #extensions-settings-button .drawer-icon:active {
        background-color: rgba(0, 0, 0, 0.18);
        box-shadow: inset 1px 1px rgba(0, 0, 0, 0.4), inset -1px -1px rgba(255, 255, 255, 0.25);
    }

    /* 打开的窗口：最大化，标题栏右上角的 × 就是原来的按钮挪过来的 */
    #top-settings-holder .drawer-content,
    #top-settings-holder .drawer-content.fillLeft {
        pointer-events: auto;
        position: fixed;
        left: 0 !important;
        top: 0 !important;
        width: 100% !important;
        min-width: 0;
        max-width: none !important;
        height: calc(100dvh - var(--xp-tb-h));
        max-height: none;
        margin: 0;
        padding: 0 8px 8px;
        box-sizing: border-box;
        background: var(--xp-face);
        border: 0;
        border-radius: 7px 7px 0 0;
        box-shadow: none;
        backdrop-filter: none;
        -webkit-backdrop-filter: none;
        color: #000;
        font: 13px/1.4 var(--xp-ui-font);
        z-index: 10;
    }

    #top-settings-holder .drawer-content:not(.openDrawer) { display: none; }
    #left-nav-panel.drawer-content.openDrawer { display: flex; flex-direction: column; }

    #top-settings-holder .drawer-content::before {
        content: var(--xp-dlg);
        position: sticky;
        top: 0;
        display: block;
        flex: none;
        margin: 0 -8px 8px;
        padding: 0 60px 0 28px;
        height: var(--xp-title-h);
        border-radius: 7px 7px 0 0;
        background: var(--xp-ico) no-repeat 7px 7px / 16px 16px, var(--xp-title-grad);
        font: 700 13px/31px var(--xp-title-font);
        color: var(--xp-title-ink);
        text-shadow: 1px 1px var(--xp-title-shadow);
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        z-index: 20;
    }

    #top-settings-holder .drawer:has(> .drawer-content.openDrawer:not(.fillRight)) > .drawer-toggle {
        position: fixed;
        left: calc(100vw - 30px);
        top: 3px;
        width: 26px;
        height: 25px;
        z-index: 3010;
    }

    #top-settings-holder .drawer:has(> .drawer-content.openDrawer:not(.fillRight)) > .drawer-toggle .drawer-icon {
        background: var(--xp-css-close) no-repeat center / 21px 21px;
        box-shadow: none;
    }

    #top-settings-holder .drawer:has(> .drawer-content.openDrawer:not(.fillRight)) > .drawer-toggle .drawer-icon::after {
        content: none;
    }

    #left-nav-panel > .topRightInset { top: 40px; }
    #left-nav-panel > #clickSlidersTips { position: static; margin: 0 0 4px; }

    /* 开始按钮 + 托盘 */
    #rightNavHolder::after {
        content: var(--xp-clock, '');
        position: absolute;
        right: 0;
        top: calc(100dvh - var(--xp-tb-h) + 10px);
        width: var(--xp-tray-w);
        height: 16px;
        padding-right: 10px;
        box-sizing: border-box;
        background:
            var(--xp-art-messenger) no-repeat right 34px top 0 / 16px 16px,
            var(--xp-art-speaker) no-repeat right 12px top 0 / 16px 16px;
        font: 12px/16px var(--xp-ui-font);
        color: var(--xp-tray-ink);
        text-align: right;
        white-space: nowrap;
        pointer-events: none;
    }

    /* 有时钟（装了主题伴侣）：手机上地方小，托盘只留音量 + 时钟 */
    html.xp-has-clock #rightNavHolder::after {
        background: var(--xp-art-speaker) no-repeat right calc(10px + var(--xp-clock-w)) top 0 / 16px 16px;
    }

    #rightNavHolder .drawer-icon {
        border-radius: 0 12px 12px 0;
        background:
            var(--xp-art-flag) no-repeat 6px center / 20px 22px,
            radial-gradient(ellipse 80% 70% at 40% 0%, rgba(255, 255, 255, 0.38), rgba(255, 255, 255, 0) 60%),
            linear-gradient(180deg, #3A9A3A 0%, #4FC34D 6%, #3EAD3B 14%, #37A034 50%, #2F8F2E 86%, #2A7F29 96%, #1F5F1F 100%);
        box-shadow: inset -2px 0 2px rgba(0, 0, 0, 0.35), inset 0 1px 1px rgba(255, 255, 255, 0.4), 2px 0 3px rgba(0, 0, 0, 0.35);
    }

    #rightNavHolder .drawer-icon::before {
        content: '开始';
        position: absolute;
        left: 30px;
        top: 0;
        font: italic 400 17px/36px SimSun, '宋体', 'Songti SC', serif !important;
        color: #FFFFFF;
        text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.55);
    }

    #rightNavHolder .drawer-icon.openIcon { filter: brightness(0.85); }

}

/* ================================================================
 * 开始菜单 = 角色面板（电脑、手机共用）
 *   顶上蓝条：头像 + 用户名；左栏白底：角色卡就是「程序」，底下「所有程序(P) ▶」；
 *   右栏浅蓝：其他面板的入口（菜单开着时，各面板的按钮挪到这里来，点了菜单收起、窗口打开，跟 XP 一样）；
 *   底栏：注销(L)、关闭计算机(U)（画的）
 * ================================================================ */
:root {
    --xp-sm-w: 600px;                /* 整个开始菜单宽 */
    --xp-sm-r: 210px;                /* 右栏宽 */
    --xp-sm-h: min(660px, calc(100dvh - var(--xp-tb-h) - 8px));
    --xp-sm-t: calc(100dvh - var(--xp-tb-h) - var(--xp-sm-h));
    --xp-sm-head: 58px;              /* 顶上蓝条 */
    --xp-sm-foot: 40px;              /* 底栏 */
    --xp-sm-item: 30px;              /* 右栏每项高 */
}

@media screen and (max-width: 1000px) {
    :root {
        --xp-sm-w: min(400px, 100vw);
        --xp-sm-r: 150px;
        --xp-sm-h: min(640px, calc(100dvh - var(--xp-tb-h) - 40px));
        --xp-sm-head: 50px;
        --xp-sm-item: 34px;
    }
}

#top-settings-holder #right-nav-panel.drawer-content {
    left: 0 !important;
    top: var(--xp-sm-t) !important;
    right: auto;
    width: var(--xp-sm-w) !important;
    height: var(--xp-sm-h);
    max-height: none;
    min-width: 0;
    margin: 0;
    padding: 0 calc(var(--xp-sm-r) + 6px) calc(var(--xp-sm-foot) + 30px) 6px;
    box-sizing: border-box;
    flex-direction: column;
    overflow: hidden;
    border: 0;
    border-radius: 7px 7px 0 0;
    background:
        linear-gradient(90deg, var(--xp-sm-col-edge), var(--xp-sm-col-edge)) right calc(var(--xp-sm-r) - 1px) top 0 / 1px 100% no-repeat,
        linear-gradient(var(--xp-sm-col), var(--xp-sm-col)) right 0 top 0 / var(--xp-sm-r) 100% no-repeat,
        /* 左栏底部的分隔线和「所有程序(P) ▶」 */
        linear-gradient(90deg, transparent, #D4D0C8 15%, #D4D0C8 85%, transparent) left 10px bottom calc(var(--xp-sm-foot) + 30px) / calc(100% - var(--xp-sm-r) - 20px) 1px no-repeat,
        var(--xp-art-allPrograms) left calc((100% - var(--xp-sm-r) - 120px) / 2) bottom calc(var(--xp-sm-foot) + 4px) / 120px 22px no-repeat,
        #FFFFFF;
    box-shadow: inset 0 0 0 1px var(--xp-sm-frame), 2px 2px 6px rgba(0, 0, 0, 0.5);
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    color: #000;
    font: 12px/1.4 var(--xp-ui-font);
    z-index: 10;
}

#top-settings-holder #right-nav-panel.drawer-content:not(.openDrawer) { display: none; }
#top-settings-holder #right-nav-panel.drawer-content.openDrawer { display: flex; }

/* 顶上：头像 + 用户名，底下一道橙线 */
#top-settings-holder #right-nav-panel.drawer-content::before {
    content: var(--xp-user);
    position: static;
    display: block;
    flex: none;
    margin: 0 calc(-1 * var(--xp-sm-r) - 6px) 6px -6px;
    height: var(--xp-sm-head);
    padding: 0 0 0 calc(var(--xp-sm-head) + 8px);
    border-radius: 7px 7px 0 0;
    background:
        var(--xp-art-userPic) no-repeat 7px center / calc(var(--xp-sm-head) - 10px) calc(var(--xp-sm-head) - 10px),
        linear-gradient(90deg, transparent, #F4B66C 30%, #E8933B 70%, transparent) left 0 bottom 0 / 100% 2px no-repeat,
        var(--xp-sm-head-grad);
    box-shadow: inset 1px 1px var(--xp-sm-head-edge);
    font: 700 14px/var(--xp-sm-head) var(--xp-title-font);
    color: var(--xp-sm-head-ink);
    text-shadow: 1px 1px 1px var(--xp-sm-head-shadow);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* 底栏：注销、关闭计算机 */
#top-settings-holder #right-nav-panel.drawer-content::after {
    content: '';
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    height: var(--xp-sm-foot);
    background:
        var(--xp-art-smShutdown) right 8px center / 118px 26px no-repeat,
        var(--xp-art-smLogoff) right 132px center / 80px 26px no-repeat,
        var(--xp-sm-foot-grad);
    box-shadow: inset 0 1px var(--xp-sm-foot-edge);
    pointer-events: none;
}

/* 左栏里的角色卡：像开始菜单里的程序。32px 方图标，名字后面一行灰色小字；鼠标移上去整行蓝底白字 */
#right-nav-panel #rm_print_characters_block .character_select,
#right-nav-panel #rm_print_characters_block .group_select {
    padding: 3px 4px;
    margin: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
}

#right-nav-panel #rm_print_characters_block .character_select:hover,
#right-nav-panel #rm_print_characters_block .group_select:hover {
    background: var(--xp-sel);
}

#right-nav-panel #rm_print_characters_block .character_select:hover *,
#right-nav-panel #rm_print_characters_block .group_select:hover * {
    color: var(--xp-sel-ink) !important;
}

#right-nav-panel #rm_print_characters_block .avatar {
    flex: none;
    width: 32px;
    height: 32px;
}

#right-nav-panel #rm_print_characters_block .avatar img {
    width: 32px;
    height: 32px;
    border-radius: 2px;
    border: 0;
    box-shadow: 1px 1px 2px rgba(0, 0, 0, 0.35);
    object-fit: cover;
}

#right-nav-panel #rm_print_characters_block .ch_name {
    font: 12px/16px var(--xp-ui-font);
    color: #000;
}

#right-nav-panel #rm_print_characters_block .ch_description,
#right-nav-panel #rm_print_characters_block .ch_add_placeholder {
    font: 11px/14px var(--xp-ui-font);
    color: #6D6D6D;
}

/* 收藏的角色 = 固定在开始菜单上的程序：名字加粗，不要金框 */
#right-nav-panel #rm_print_characters_block .character_select.is_fav .ch_name {
    font-weight: 700;
    color: #000;
}

#right-nav-panel #rm_print_characters_block .character_select.is_fav .avatar {
    outline: 0;
    border: 0;
}

/* 左栏上半部分：锁、角色列表按钮、收藏的快捷头像排成一行小工具栏 */
#right-nav-panel #right-nav-panelheader { display: none; }

#right-nav-panel #CharListButtonAndHotSwaps {
    align-items: center;
    gap: 2px;
    min-height: 28px;
    padding: 0 0 4px;
    border-bottom: 1px solid #E3E1D5;
}

#right-nav-panel #CharListButtonAndHotSwaps > .flexFlowColumn {
    flex-direction: row;
    gap: 2px;
}

#right-nav-panel .right_menu_button {
    width: 24px;
    height: 24px;
    padding: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 13px;
    color: #000;
    opacity: 1;
    filter: none;
    border: 1px solid transparent;
    border-radius: 3px;
}

#right-nav-panel .right_menu_button:hover {
    border-color: #CECECE #8E8F8F #8E8F8F #CECECE;
    background: #F0F4FD;
}

/* 收藏角色的快捷头像：24px 方块 */
#right-nav-panel #HotSwapWrapper .hotswap {
    justify-content: flex-start;
    gap: 3px;
}

#right-nav-panel #HotSwapWrapper .avatar {
    width: 24px;
    height: 24px;
    flex: none;
}

#right-nav-panel #HotSwapWrapper .avatar img {
    width: 24px;
    height: 24px;
    border-radius: 2px;
    border: 0;
    box-shadow: 1px 1px 2px rgba(0, 0, 0, 0.35);
}

/* 正在聊的角色名：「正在对话：沈栖」 */
#right-nav-panel #rm_button_selected_ch {
    opacity: 1;
}

#right-nav-panel #rm_button_selected_ch h2 {
    margin: 4px 0;
    font: 700 12px/18px var(--xp-ui-font);
    color: #000;
}

#right-nav-panel #rm_button_selected_ch h2:not(:empty)::before {
    content: '正在对话：';
    font-weight: 400;
    color: #444;
}

/* 工具栏、翻页的按钮：开始菜单里是平的，鼠标移上去才出边框（XP 工具栏那样） */
#right-nav-panel #rm_button_bar .menu_button,
#right-nav-panel #rm_print_characters_pagination .menu_button,
#right-nav-panel #rm_print_characters_pagination .paginationjs-pages li > a,
#right-nav-panel #charListGridToggle,
#right-nav-panel #bulkEditButton {
    min-width: 24px;
    min-height: 24px;
    padding: 0 4px;
    border: 1px solid transparent;
    background: transparent;
    box-shadow: none;
}

#right-nav-panel #rm_button_bar .menu_button:hover,
#right-nav-panel #rm_print_characters_pagination .menu_button:hover,
#right-nav-panel #rm_print_characters_pagination .paginationjs-pages li > a:hover,
#right-nav-panel #charListGridToggle:hover,
#right-nav-panel #bulkEditButton:hover {
    border-color: #CECECE #8E8F8F #8E8F8F #CECECE;
    background: #F0F4FD;
    box-shadow: none;
}

#right-nav-panel #rm_print_characters_pagination {
    font-size: 12px;
}

/* 标签筛选：XP 的小按钮样子 */
#right-nav-panel .tags .tag,
#right-nav-panel .tags .tag .tag_name {
    opacity: 1;
    color: #000 !important;
}

#right-nav-panel .tags .tag {
    border: 1px solid #ACA899;
    border-radius: 2px;
    background: #F5F4EA;
    color: #000;
    font-size: 12px;
}

/* 菜单开着时：各面板的按钮挪到右栏 */
#top-settings-holder #WI-SP-button { --xp-sm-label: '我的文档'; --xp-sm-i: 0; --xp-sm-sep: 0px; --xp-sm-wt: 700; }
#top-settings-holder #user-settings-button { --xp-sm-label: '我的电脑'; --xp-sm-i: 1; --xp-sm-sep: 0px; --xp-sm-wt: 700; }
#top-settings-holder #sys-settings-button { --xp-sm-label: '网上邻居'; --xp-sm-i: 2; --xp-sm-sep: 0px; --xp-sm-wt: 700; }
#top-settings-holder #extensions-settings-button { --xp-sm-label: '控制面板(C)'; --xp-sm-i: 3; --xp-sm-sep: 9px; --xp-sm-wt: 400; }
#top-settings-holder #backgrounds-button { --xp-sm-label: '显示属性'; --xp-sm-i: 4; --xp-sm-sep: 9px; --xp-sm-wt: 400; }
#top-settings-holder #persona-management-button { --xp-sm-label: '我的个人资料'; --xp-sm-i: 5; --xp-sm-sep: 9px; --xp-sm-wt: 400; }
#top-settings-holder #ai-config-button { --xp-sm-label: '回复方式'; --xp-sm-i: 6; --xp-sm-sep: 18px; --xp-sm-wt: 400; }
#top-settings-holder #advanced-formatting-button { --xp-sm-label: '消息格式'; --xp-sm-i: 7; --xp-sm-sep: 18px; --xp-sm-wt: 400; }

/* 右栏的分隔线（借开始按钮那一格的 ::before 画） */
#top-settings-holder:has(#right-nav-panel.openDrawer) #rightNavHolder::before {
    content: '';
    position: absolute;
    left: calc(var(--xp-sm-w) - var(--xp-sm-r) + 10px);
    width: calc(var(--xp-sm-r) - 20px);
    top: calc(var(--xp-sm-t) + var(--xp-sm-head) + 6px + 3 * var(--xp-sm-item) + 4px);
    height: calc(3 * var(--xp-sm-item) + 10px);
    border-top: 1px solid var(--xp-sm-col-edge);
    border-bottom: 1px solid var(--xp-sm-col-edge);
    background: none;
    font-size: 0;
    z-index: 11;
    pointer-events: none;
}

#top-settings-holder:has(#right-nav-panel.openDrawer) > .drawer:is(#WI-SP-button, #user-settings-button, #sys-settings-button, #extensions-settings-button, #backgrounds-button, #persona-management-button, #ai-config-button, #advanced-formatting-button) > .drawer-toggle {
    position: fixed;
    left: calc(var(--xp-sm-w) - var(--xp-sm-r) + 4px);
    top: calc(var(--xp-sm-t) + var(--xp-sm-head) + 6px + var(--xp-sm-i) * var(--xp-sm-item) + var(--xp-sm-sep));
    width: calc(var(--xp-sm-r) - 8px);
    height: var(--xp-sm-item);
    z-index: 12;
}

#top-settings-holder:has(#right-nav-panel.openDrawer) > .drawer:is(#WI-SP-button, #user-settings-button, #sys-settings-button, #extensions-settings-button, #backgrounds-button, #persona-management-button, #ai-config-button, #advanced-formatting-button) > .drawer-toggle .drawer-icon {
    background: var(--xp-ico) no-repeat 4px center / 24px 24px;
    border-radius: 0;
    box-shadow: none;
}

#top-settings-holder:has(#right-nav-panel.openDrawer) > .drawer:is(#WI-SP-button, #user-settings-button, #sys-settings-button, #extensions-settings-button, #backgrounds-button, #persona-management-button, #ai-config-button, #advanced-formatting-button) > .drawer-toggle .drawer-icon::after {
    content: var(--xp-sm-label);
    display: block;
    position: absolute;
    left: 34px;
    top: 0;
    font: var(--xp-sm-wt) 12px/var(--xp-sm-item) var(--xp-ui-font);
    color: var(--xp-sm-ink);
    white-space: nowrap;
    text-align: left;
}

#top-settings-holder:has(#right-nav-panel.openDrawer) > .drawer:is(#WI-SP-button, #user-settings-button, #sys-settings-button, #extensions-settings-button, #backgrounds-button, #persona-management-button, #ai-config-button, #advanced-formatting-button) > .drawer-toggle .drawer-icon:hover {
    background-color: var(--xp-sel);
}

#top-settings-holder:has(#right-nav-panel.openDrawer) > .drawer:is(#WI-SP-button, #user-settings-button, #sys-settings-button, #extensions-settings-button, #backgrounds-button, #persona-management-button, #ai-config-button, #advanced-formatting-button) > .drawer-toggle .drawer-icon:hover::after {
    color: var(--xp-sel-ink);
}

/* ================================================================
 * 面板里的控件：XP 的按钮、输入框、下拉框、复选框、滑块、分组标题、菜单、消息框、气球提示
 * 照「显示 属性」对话框（美术参考/win XP/imgi_3）和 XP.css
 * ================================================================ */
@media screen and (max-width: 1000px) {
    :root { --mainFontSize: 13px; }
}

#top-settings-holder .drawer-content,
.popup,
#options,
#extensionsMenu {
    font-family: var(--xp-ui-font);
    color: #000;
}

#top-settings-holder .drawer-content h3,
#top-settings-holder .drawer-content h4,
#top-settings-holder .drawer-content h5,
.popup h3,
.popup h4 {
    font-family: var(--xp-ui-font);
    font-weight: 700;
    color: #000;
}

#top-settings-holder .drawer-content h3 { font-size: 13px; }
#top-settings-holder .drawer-content h4 { font-size: 12px; }

#top-settings-holder .drawer-content small,
#top-settings-holder .drawer-content .notes-link,
#top-settings-holder .drawer-content .text_muted {
    color: #444;
    opacity: 1;
}

#top-settings-holder .drawer-content a {
    color: #0000FF;
}

/* ---- 按钮：白到米色的渐变，深蓝细边，圆角 3；鼠标移上去一圈橙光，按下去变灰 ---- */
.menu_button,
.popup .popup-controls .menu_button,
#top-settings-holder .drawer-content .menu_button {
    min-height: 23px;
    padding: 2px 8px;
    border: 1px solid var(--xp-btn-edge);
    border-radius: 3px;
    background: linear-gradient(180deg, #FFFFFF 0%, #ECEBE5 86%, #D8D0C4 100%);
    color: #000;
    opacity: 1;
    filter: none;
    font-family: var(--xp-ui-font);
    font-size: 12px;
    box-shadow: none;
    transition: none;
}

.menu_button:hover,
#top-settings-holder .drawer-content .menu_button:hover {
    background: linear-gradient(180deg, #FFFFFF 0%, #ECEBE5 86%, #D8D0C4 100%);
    box-shadow: inset -1px 1px #FFF0CF, inset 1px 2px #FDD889, inset -2px 2px #FBC761, inset 2px -2px #E5A01A;
    color: #000;
}

.menu_button:active {
    background: linear-gradient(180deg, #CDCAC3 0%, #E3E3DB 8%, #E5E5DE 94%, #F2F2F1 100%);
    box-shadow: none;
}

/* 打开 / 选中状态的按钮（酒馆的 .active、.toggleEnabled 等）：像按下去没弹起来 */
.menu_button.active,
.menu_button.toggleEnabled,
.menu_button.selected {
    background: linear-gradient(180deg, #CDCAC3 0%, #E3E3DB 8%, #E5E5DE 94%, #F2F2F1 100%);
    box-shadow: inset 1px 1px #A6A39A;
    color: #000;
}

/* 危险按钮：XP 没有红按钮，字变深红 */
.menu_button.redWarningBG,
.menu_button.caution {
    background: linear-gradient(180deg, #FFFFFF 0%, #ECEBE5 86%, #D8D0C4 100%);
    color: #B00000;
}

/* 弹窗里的「确定」：默认按钮多一圈蓝色焦点框 */
.popup .popup-controls .menu_button.popup-button-ok,
.menu_button.menu_button_default {
    box-shadow: inset -1px 1px #CEE7FF, inset 1px 2px #98B8EA, inset -2px 2px #BCD4F6, inset 1px -1px #89ADE4, inset 2px -2px #89ADE4;
    color: #000;
}

/* 小图标按钮（酒馆很多 fa 图标是 .menu_button）：字色实黑，不要 40% 透明 */
.menu_button.fa-solid,
.menu_button i,
#top-settings-holder .drawer-content .menu_button.fa-solid,
#top-settings-holder .drawer-content .right_menu_button,
#top-settings-holder .drawer-content .inline-drawer-icon {
    color: #000;
    opacity: 1;
    filter: none;
}

/* 上面给按钮换了宋体，图标按钮要把 Font Awesome 换回来，不然图标变方框 */
.menu_button:is(.fa-solid, .fas, .fa),
.menu_button:is(.fa-solid, .fas, .fa)::before {
    font-family: 'Font Awesome 6 Free' !important;
    font-weight: 900;
}

.menu_button:is(.fa-regular, .far),
.menu_button:is(.fa-regular, .far)::before {
    font-family: 'Font Awesome 6 Free' !important;
    font-weight: 400;
}

.menu_button.fa-brands,
.menu_button.fa-brands::before {
    font-family: 'Font Awesome 6 Brands' !important;
}

/* 面板里的小字：宋体小于 12px 就糊了（没有点阵），统一不小于 12px */
#top-settings-holder .drawer-content :is(small, label, .checkbox_label, .range-block-title, .range-block-counter, .notes-link, .toggle-description, span:not([class*="fa-"])) {
    font-size: max(12px, 1em);
}

#top-settings-holder .drawer-content :is(select, input, textarea, .text_pole),
.popup :is(select, input, textarea, .text_pole) {
    font-size: 12px;
}

/* ---- 输入框、文本框、下拉框：白底，蓝灰细边，直角 ---- */
.text_pole,
input[type="text"],
input[type="number"],
input[type="search"],
input[type="password"],
input[type="url"],
textarea,
select,
.select2-container .select2-selection {
    border: 1px solid var(--xp-input-edge) !important;
    border-radius: 0 !important;
    background-color: #FFFFFF !important;
    color: #000;
    font-family: var(--xp-ui-font);
    box-shadow: none;
    outline: none;
}

/* 对话的输入框本身没有框（框是外面那个白色圆角块） */
#send_textarea {
    border: 0 !important;
    background-color: transparent !important;
}

.text_pole:focus,
textarea:focus,
select:focus {
    outline: none;
    box-shadow: none;
    border-color: var(--xp-input-edge) !important;
}

/* 下拉框：右边那个浅蓝的小按钮 */
select:not([multiple]) {
    appearance: none;
    -webkit-appearance: none;
    padding-right: 22px;
    background-image: var(--xp-css-dropdown) !important;
    background-repeat: no-repeat !important;
    background-position: right 1px center !important;
    background-size: 15px 17px !important;
}

select:not([multiple]):hover { background-image: var(--xp-css-dropdown-hover) !important; }
select:not([multiple]):active { background-image: var(--xp-css-dropdown-active) !important; }

select option {
    background: #FFFFFF;
    color: #000;
}

::selection {
    background: var(--xp-sel);
    color: var(--xp-sel-ink);
}

/* ---- 复选框：13×13，深蓝边、白到浅灰的渐变；勾是绿的 ---- */
input[type="checkbox"] {
    width: 13px;
    height: 13px;
    min-width: 13px;
    border: 1px solid #1D5281;
    border-radius: 0;
    outline: none;
    background: linear-gradient(135deg, #DCDCD7 0%, #FFFFFF 100%) !important;
    box-shadow: none;
    transform: none;
}

input[type="checkbox"]::before {
    display: none;
}

input[type="checkbox"]:checked {
    border-color: #1D5281;
    background: var(--xp-css-checkmark) center / 11px 11px no-repeat, linear-gradient(135deg, #DCDCD7 0%, #FFFFFF 100%) !important;
}

input[type="checkbox"]:hover:not(:disabled) {
    box-shadow: inset -2px -2px #F8B636, inset 2px 2px #FEDF9C;
}

input[type="checkbox"]:disabled {
    border-color: #CAC8BB;
    background: #FFFFFF !important;
}

/* ---- 单选框：圆的，点是绿的 ---- */
input[type="radio"] {
    appearance: none;
    -webkit-appearance: none;
    width: 13px;
    height: 13px;
    min-width: 13px;
    margin: 0 4px 0 0;
    border: 1px solid #1D5281;
    border-radius: 50%;
    background: linear-gradient(135deg, #DCDCD7 0%, #FFFFFF 100%);
    vertical-align: middle;
}

input[type="radio"]:checked {
    background: var(--xp-css-radio-dot) center / 5px 5px no-repeat, linear-gradient(135deg, #DCDCD7 0%, #FFFFFF 100%);
}

input[type="radio"]:hover:not(:disabled) {
    box-shadow: inset -2px -2px #F8B636, inset 2px 2px #FEDF9C;
}

/* ---- 滑块：凹下去的细槽 + XP 的尖头滑块 ---- */
input[type="range"] {
    appearance: none;
    -webkit-appearance: none;
    background: transparent;
    height: 22px;
}

input[type="range"]::-webkit-slider-runnable-track {
    height: 2px;
    background: #ECEBE4;
    border-radius: 2px;
    box-shadow: 1px 0 0 #fff, 1px 1px 0 #fff, 0 1px 0 #fff, -1px 0 0 #9D9C99, -1px -1px 0 #9D9C99, 0 -1px 0 #9D9C99, -1px 1px 0 #fff, 1px -1px #9D9C99;
}

input[type="range"]::-webkit-slider-thumb {
    appearance: none;
    -webkit-appearance: none;
    width: 11px;
    height: 21px;
    border: 0;
    border-radius: 0;
    background: var(--xp-css-indicator-horizontal) center / 11px 21px no-repeat;
    box-shadow: none;
    transform: translateY(-9px);
}

.neo-range-slider {
    height: 2px !important;
    background: #ECEBE4 !important;
    box-shadow: 1px 1px 0 #fff, -1px -1px 0 #9D9C99 !important;
}

/* ---- 分组标题（可折叠的那些）：XP 任务窗格的样子，白到浅蓝的渐变、蓝色粗体字 ---- */
#top-settings-holder .drawer-content .inline-drawer-toggle.inline-drawer-header,
.popup .inline-drawer-toggle.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header {
    padding: 3px 6px 3px 10px;
    min-height: 23px;
    border: 0;
    border-left: 0;
    border-radius: 3px 3px 0 0;
    background: var(--xp-side-head);
    font-family: var(--xp-ui-font);
    font-weight: 700;
    color: var(--xp-link);
}

#top-settings-holder .drawer-content .inline-drawer-toggle.inline-drawer-header:hover {
    color: var(--xp-link-hover);
}

#top-settings-holder .drawer-content .inline-drawer-toggle.inline-drawer-header b,
#top-settings-holder .drawer-content .inline-drawer-toggle.inline-drawer-header span {
    color: inherit;
}

/* 折叠箭头换成 XP 任务窗格的圆钮 */
#top-settings-holder .drawer-content .inline-drawer-header .inline-drawer-icon,
.popup .inline-drawer-header .inline-drawer-icon {
    width: 16px;
    height: 16px;
    font-size: 0 !important;
    background: var(--xp-art-chevDown) center / 16px 16px no-repeat;
}

#top-settings-holder .drawer-content .inline-drawer-header .inline-drawer-icon::before,
.popup .inline-drawer-header .inline-drawer-icon::before {
    content: none !important;
}

#top-settings-holder .drawer-content .inline-drawer-header .inline-drawer-icon.up,
.popup .inline-drawer-header .inline-drawer-icon.up {
    background-image: var(--xp-art-chevUp);
}

#top-settings-holder .drawer-content .inline-drawer-content,
#extensions_settings .inline-drawer-content,
#extensions_settings2 .inline-drawer-content {
    border: 1px solid var(--xp-side-edge);
    border-top: 0;
    background: #F7F8FC;
    padding: 6px 8px;
}

/* 用户设置里的小标题：XP 分组框（细边框 + 标题压在边上）那种蓝字 */
#user-settings-block h4,
.standoutHeader {
    background: none;
    border-left: 0;
    padding: 0;
    color: var(--xp-group-ink);
    font-weight: 400;
}

/* ---- 菜单（≡ 动作菜单、表情符号菜单）：XP 右键菜单，白底灰边，悬停蓝底白字 ---- */
#options .options-content,
#extensionsMenu {
    padding: 2px;
    background: #FFFFFF;
    border: 1px solid #ACA899;
    border-radius: 0;
    box-shadow: 2px 2px 3px rgba(0, 0, 0, 0.35);
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
}

#options .options-content a,
#extensionsMenu .list-group-item,
#extensionsMenu > .extension_container > div {
    padding: 3px 20px 3px 6px;
    border: 0;
    border-radius: 0;
    background: transparent;
    font: 12px/18px var(--xp-ui-font);
    color: #000;
    opacity: 1;
}

#options .options-content a:hover,
#extensionsMenu .list-group-item:hover,
#extensionsMenu > .extension_container > div:hover {
    background: var(--xp-sel);
    color: var(--xp-sel-ink);
}

#options .options-content a:hover *,
#extensionsMenu .list-group-item:hover *,
#extensionsMenu > .extension_container > div:hover * {
    color: var(--xp-sel-ink);
}

#options .options-content hr {
    margin: 3px 2px;
    height: 1px;
    background: #ACA899;
    opacity: 1;
}

/* ---- 弹窗：XP 消息框（蓝标题栏 + 米色底），标题栏写「XP Messenger」 ---- */
.popup {
    padding: 0 12px 10px;
    border: 0;
    border-radius: 8px 8px 0 0;
    background: var(--xp-face);
    box-shadow: var(--xp-frame-shadow), 4px 4px 12px rgba(0, 0, 0, 0.35);
    color: #000;
    font-size: 12px;
}

.popup::before {
    content: 'XP Messenger';
    display: block;
    flex: none;
    margin: 0 -12px 6px;
    padding: 0 30px 0 8px;
    height: var(--xp-title-h);
    border-radius: 8px 8px 0 0;
    background: var(--xp-css-close) no-repeat right 6px top 5px / 21px 21px, var(--xp-title-grad);
    box-shadow: var(--xp-title-edge);
    font: 700 13px/31px var(--xp-title-font);
    color: var(--xp-title-ink);
    text-align: left;
    text-shadow: 1px 1px var(--xp-title-shadow) !important;
}

.popup .popup-controls {
    gap: 6px;
}

/* XP 弹消息框时后面不会变暗变糊 */
.popup::backdrop {
    background: transparent;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
}

.popup .popup-controls .menu_button {
    min-width: 75px;
}

/* ---- 通知：托盘上冒出来的黄色气球 ---- */
#toast-container.toast-bottom-right {
    right: 6px;
    bottom: calc(var(--xp-tb-h) + 4px);
}

#toast-container > .toast,
#toast-container > div {
    width: 300px;
    margin: 0 0 14px;
    padding: 8px 10px 9px 40px;
    background: #FFFFE1 no-repeat 10px 9px / 20px 20px !important;
    background-image: var(--xp-art-info) !important;
    border: 1px solid #000000;
    border-left: 1px solid #000000;
    border-radius: 7px;
    box-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
    color: #000;
    opacity: 1;
    font: 12px/1.5 var(--xp-ui-font);
    overflow: visible;
}

#toast-container > .toast-success { background-image: var(--xp-art-ok) !important; }
#toast-container > .toast-warning { background-image: var(--xp-art-warn) !important; }
#toast-container > .toast-error { background-image: var(--xp-art-error) !important; }

/* 气球的小尾巴，指着右下角的托盘 */
#toast-container > .toast::after {
    content: '';
    position: absolute;
    right: 30px;
    bottom: -13px;
    width: 14px;
    height: 13px;
    background: linear-gradient(to top right, transparent calc(50% - 0.7px), #000 calc(50% - 0.7px), #000 calc(50% + 0.7px), #FFFFE1 calc(50% + 0.7px));
    clip-path: polygon(0 0, 100% 0, 100% 100%);
}

#toast-container > .toast .toast-title {
    font-weight: 700;
    margin-bottom: 2px;
}

#toast-container > .toast .toast-close-button {
    width: 14px;
    height: 14px;
    top: 0;
    right: -2px;
    font-size: 0;
    background: var(--xp-art-balloonClose) center / 14px 14px no-repeat;
    opacity: 1;
}

/* ================================================================
 * 文字通用
 * ================================================================ */
#chat .mes .mes_text q::before,
#chat .mes .mes_text q::after {
    content: none;
}

/* 代码：XP 的等宽中文字是新宋体。代码块做成记事本那样的白框 */
#chat .mes .mes_text code {
    font-family: 'Courier New', NSimSun, '新宋体', monospace;
    font-size: 0.93em;
    padding: 0 2px;
    background: #F1EFE2;
    border: 1px solid #D4D0C8;
    border-radius: 0;
    color: #000;
}

#chat .mes .mes_text pre {
    margin: 4px 0 8px;
    padding: 0;
    background: #FFFFFF;
    border: 1px solid var(--xp-input-edge);
    border-radius: 0;
}

#chat .mes .mes_text pre code,
#chat .mes .mes_text pre code.hljs {
    display: block;
    padding: 4px 6px;
    font: 13px/1.5 'Courier New', NSimSun, '新宋体', monospace;
    background: transparent;
    border: 0;
    color: #000;
    white-space: pre-wrap;
}

#chat .mes .mes_text pre code * {
    color: inherit !important;
    font-style: normal !important;
    font-weight: inherit !important;
}

/* 引用：Messenger 没有，按旧邮件的「> 」样式，左边一道灰线 */
#chat .mes .mes_text blockquote {
    margin: 4px 0;
    padding: 0 0 0 8px;
    border-left: 2px solid #ACA899;
    color: #333;
}

/* 心理话：楷体（中文 XP 自带的「楷体_GB2312」），不倾斜也看得出是另一种声音 */
#chat .mes .mes_text em {
    font-family: KaiTi, '楷体', 'KaiTi_GB2312', STKaiti, serif;
    font-style: normal;
}

/* 「思考了一会」：XP 任务窗格那种可折叠的小标题 */
#chat .mes .mes_reasoning_details {
    margin: 2px 8px 4px 15px;
}

#chat .mes .mes_reasoning_header {
    padding: 1px 8px 1px 6px;
    background: var(--xp-side-head);
    border: 1px solid var(--xp-side-edge);
    border-radius: 3px 3px 0 0;
    font: 700 12px/18px var(--xp-ui-font);
    color: var(--xp-link);
}

#chat .mes .mes_reasoning_header .mes_reasoning_header_title {
    font: inherit;
    color: inherit;
}

#chat .mes .mes_reasoning_arrow {
    color: var(--xp-link);
    opacity: 1;
}

#chat .mes .mes_reasoning {
    margin: 0;
    padding: 6px 8px;
    background: var(--xp-side-box);
    border: 1px solid var(--xp-side-edge);
    border-top: 0;
    font: 12px/1.6 var(--xp-ui-font);
    color: #000;
}

/* 换回复的箭头、计数 */
#chat .mes .swipe_left,
#chat .mes .swipe_right {
    color: var(--xp-link);
    opacity: 1;
    font-size: 14px;
}

#chat .mes .swipes-counter {
    font: 11px/1 Tahoma, sans-serif;
    color: var(--xp-meta);
    opacity: 1 !important;
}

/* 托盘时钟：主题伴侣每分钟把「15:45」写进 --xp-clock，并给 html 加 .xp-has-clock */
html.xp-has-clock { --xp-clock-w: 44px; }

@media screen and (max-width: 1000px) {
    /* 手机上 html 高度是 0：body 的背景会被挪到画布上、按 html 定位，任务栏画到了屏幕外。
     * 给 html 自己一个底色，body 的背景就留在 body 里 */
    html:root { background: var(--xp-desktop); }
    :root { --xp-tray-w: 58px; }
    html.xp-has-clock { --xp-tray-w: 80px; }
}

/* ================================================================
 * 启动页：XP 登录后的「欢迎使用」那一屏（照 美术参考/win XP 百度百科那张）
 * 上下两条深蓝（下面那条从左往右由蓝紫变深蓝），中间平涂亮蓝，上沿一道白光、下沿一道淡橙光；只有一行斜体宋体「欢迎使用」
 * 只在酒馆刚启动时出现（那时页面上还有 #preloader）
 * ================================================================ */
:root {
    --xp-welcome-bar: #012F9C;
    --xp-welcome-bar-l: #3332AB;     /* 底条左端的蓝紫 */
    --xp-welcome-mid: #597CDB;
    --xp-welcome-line: rgba(255, 255, 255, 0.75);
    --xp-welcome-orange: rgba(249, 151, 54, 0.6);
    --xp-welcome-ink: #EEF2FB;
    --xp-welcome-top: 16%;
    --xp-welcome-bottom: 20%;
}

/* 酒馆给这个弹窗写死了 90% 宽高（!important），撑满全屏 */
body:has(#preloader) dialog.popup:has(#loader) {
    position: fixed;
    inset: 0;
    width: 100vw !important;
    height: 100dvh !important;
    max-width: none !important;
    max-height: none !important;
    min-width: 0;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 0;
    box-shadow: none;
    animation: none;
    overflow: hidden;
    color: var(--xp-welcome-ink);
    font-family: var(--xp-ui-font);
    background:
        linear-gradient(90deg, transparent 5%, var(--xp-welcome-line) 35%, transparent 80%) no-repeat 0 var(--xp-welcome-top) / 100% 2px,
        linear-gradient(90deg, transparent 2%, var(--xp-welcome-orange) 25%, rgba(255, 255, 255, 0.35) 55%, transparent 90%) no-repeat 0 calc(100% - var(--xp-welcome-bottom)) / 100% 2px,
        linear-gradient(var(--xp-welcome-bar), var(--xp-welcome-bar)) no-repeat 0 0 / 100% var(--xp-welcome-top),
        linear-gradient(90deg, var(--xp-welcome-bar-l), var(--xp-welcome-bar)) no-repeat 0 100% / 100% var(--xp-welcome-bottom),
        var(--xp-welcome-mid);
}

body:has(#preloader) dialog.popup:has(#loader)::before {
    content: none;
}

body:has(#preloader) dialog.popup:has(#loader)::backdrop {
    background: var(--xp-welcome-mid);
    backdrop-filter: none;
}

body:has(#preloader) dialog.popup:has(#loader) .popup-body,
body:has(#preloader) dialog.popup:has(#loader) .popup-content {
    position: static;
    width: 100%;
    height: 100%;
    max-height: none;
    margin: 0;
    padding: 0;
    overflow: visible;
    background: none;
}

/* 转圈、logo、Initializing… 都不要，只留一行字 */
body:has(#preloader) #loader,
body:has(#preloader) #loader.splash-screen {
    position: fixed;
    inset: var(--xp-welcome-top) 0 var(--xp-welcome-bottom);
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0;
    width: auto;
    height: auto;
    background: none;
}

body:has(#preloader) #loader > :is(.splash-logo, .splash-message, #load-spinner) {
    display: none;
}

body:has(#preloader) #loader::before {
    content: '欢迎使用';
    margin: 0 0 2% 22%;
    font: italic 400 min(10dvh, 17vw)/1.2 SimSun, '宋体', 'Songti SC', serif;
    letter-spacing: 0.06em;
    color: var(--xp-welcome-ink);
    text-shadow: 2px 2px 3px rgba(0, 0, 0, 0.35);
}

@media screen and (max-width: 1000px) {
    body:has(#preloader) #loader::before {
        margin: 0;
    }
}
/* ==== end themes/xp/base.css ==== */
